#define BCM2712_FIRMWARE_GET_CLOCK_RATE 0x00030002u
#define BCM2712_FIRMWARE_SET_CLOCK_RATE 0x00038002u
#define BCM2712_HDMI_CLOCK_ID 13u
#define BCM2712_BVB_CLOCK_ID 14u
#define BCM2712_HVS_CORE_CLOCK_ID 4u
#define BCM2712_HVS_DISPLAY_CLOCK_ID 16u
