#define BCM2712_FIRMWARE_MAILBOX_MAIL1_STATUS 0x38u
#define BCM2712_FIRMWARE_MAILBOX_FULL (1u << 31)
#define BCM2712_FIRMWARE_MAILBOX_EMPTY (1u << 30)
#define BCM2712_FIRMWARE_MAILBOX_STATUS_REQUEST 0x00000000u
