static int rp1_tree_root_bus_candidate(
    const os_device_tree *tree,
    usize candidate_index
)
{
    if (tree == (const os_device_tree *)0
        || candidate_index >= tree->node_count) {
        return 0;
    }

    const os_device_tree_node *candidate = &tree->nodes[candidate_index];
    if (!candidate->enabled
        || !expected_compatible(candidate, "simple-bus")
        || !candidate->ranges_present
        || candidate->range_count == 0u
        || candidate->name[0] != 'r'
        || candidate->name[1] != 'p'
        || candidate->name[2] != '1'
        || (candidate->name[3] != '\0'
            && candidate->name[3] != '@')
        || candidate->parent_index >= tree->node_count
        || candidate->parent_index == candidate_index) {
        return 0;
    }

    const os_device_tree_node *host =
        &tree->nodes[candidate->parent_index];
    return host->enabled
        && expected_compatible(host, "brcm,bcm2712-pcie");
}

static int rp1_tree_find_root_bus(
    const os_device_tree *tree,
    usize *root_index_out
)
{
    if (root_index_out != (usize *)0) {
        *root_index_out = 0u;
    }
    if (tree == (const os_device_tree *)0
        || tree->node_count == 0u
        || tree->node_count > OS_DEVICE_TREE_MAX_NODES
        || root_index_out == (usize *)0) {
        return 0;
    }

    usize root_index = tree->node_count;
    for (usize i = 0u; i < tree->node_count; ++i) {
        if (!rp1_tree_root_bus_candidate(tree, i)) {
            continue;
        }
        if (root_index != tree->node_count) {
            return 0;
        }
        root_index = i;
    }
    if (root_index == tree->node_count) {
        return 0;
    }
    *root_index_out = root_index;
    return 1;
}

static int rp1_tree_find_ancestor_rp1_root(
    const os_device_tree *tree,
    usize node_index,
    usize *ancestor_index_out
)
{
    if (ancestor_index_out != (usize *)0) {
        *ancestor_index_out = 0u;
    }
    if (tree == (const os_device_tree *)0
        || ancestor_index_out == (usize *)0
        || node_index >= tree->node_count) {
        return 0;
    }

    usize root_index = 0u;
    int branch_enabled = 0;
    if (!rp1_tree_find_root_bus(tree, &root_index)
        || !rp1_tree_branch_state(
            tree, node_index, root_index, &branch_enabled)
        || !branch_enabled) {
        return 0;
    }
    *ancestor_index_out = root_index;
    return 1;
}

static int rp1_child_node_valid(
    const os_pi5_rp1_pci *rp1,
    const os_device_tree *tree,
    const os_device_tree_node *node
)
{
    if (rp1 == (const os_pi5_rp1_pci *)0 || !rp1->ready
        || rp1->host_node == (const os_device_tree_node *)0
        || rp1->function.vendor_id != OS_PI5_PCI_VENDOR_RPI
        || rp1->function.device_id != OS_PI5_PCI_DEVICE_RP1_C0
        || tree == (const os_device_tree *)0
        || tree->node_count == 0u
        || tree->node_count > OS_DEVICE_TREE_MAX_NODES
        || node == (const os_device_tree_node *)0
        || !node->enabled) {
        return 0;
    }

    usize host_index = tree->node_count;
    usize node_index = tree->node_count;
    for (usize i = 0; i < tree->node_count; ++i) {
        if (&tree->nodes[i] == rp1->host_node) {
            host_index = i;
        }
        if (&tree->nodes[i] == node) {
            node_index = i;
        }
    }
    if (host_index == tree->node_count
        || node_index == tree->node_count
        || node_index == host_index
        || !rp1->host_node->enabled
        || !expected_compatible(rp1->host_node, "brcm,bcm2712-pcie")) {
        return 0;
    }

    usize rp1_bus_index = 0u;
    if (!rp1_tree_find_ancestor_rp1_root(
            tree, node_index, &rp1_bus_index)
        || tree->nodes[rp1_bus_index].parent_index != host_index) {
        return 0;
    }

    return 1;
}

static void mmio_barrier(void)
{
#if defined(__aarch64__)
    __asm__ volatile("dmb osh" ::: "memory");
#elif defined(__x86_64__)
    __asm__ volatile("mfence" ::: "memory");
#else
    __atomic_thread_fence(__ATOMIC_SEQ_CST);
#endif
}

static int direct_read8(
    void *context,
    u32 region,
    u32 offset,
    u8 *value
)
{
    os_pi5_mmio_direct *direct = (os_pi5_mmio_direct *)context;
    if (direct == (os_pi5_mmio_direct *)0
        || region >= OS_DEVICE_TREE_MAX_REGIONS
        || direct->region_bases[region] == (volatile u32 *)0
        || offset >= direct->region_sizes[region]
        || value == (u8 *)0) {
        return 0;
    }
    mmio_barrier();
    *value = *((volatile u8 *)direct->region_bases[region] + offset);
    mmio_barrier();
    return 1;
}

static int direct_write8(
    void *context,
    u32 region,
    u32 offset,
    u8 value
)
{
    os_pi5_mmio_direct *direct = (os_pi5_mmio_direct *)context;
    if (direct == (os_pi5_mmio_direct *)0
        || region >= OS_DEVICE_TREE_MAX_REGIONS
        || direct->region_bases[region] == (volatile u32 *)0
        || offset >= direct->region_sizes[region]) {
        return 0;
    }
    mmio_barrier();
    *((volatile u8 *)direct->region_bases[region] + offset) = value;
    mmio_barrier();
    return 1;
}

static int direct_read16(
    void *context,
    u32 region,
    u32 offset,
    u16 *value
)
{
    os_pi5_mmio_direct *direct = (os_pi5_mmio_direct *)context;
    if (direct == (os_pi5_mmio_direct *)0
        || region >= OS_DEVICE_TREE_MAX_REGIONS
        || direct->region_bases[region] == (volatile u32 *)0
        || offset > direct->region_sizes[region]
        || sizeof(u16) > direct->region_sizes[region] - offset
        || (offset & 1u) != 0
        || value == (u16 *)0) {
        return 0;
    }
    mmio_barrier();
    *value = *(volatile u16 *)(
        (volatile u8 *)direct->region_bases[region] + offset);
    mmio_barrier();
    return 1;
}

