static const os_rp1_gpio_bank g_rp1_gpio_banks[] = {
    {0u, 28u, 0x0000u, 0x0000u, 0x0004u, 0x011cu, 0x0124u},
    {28u, 6u, 0x4000u, 0x4000u, 0x4004u, 0x411cu, 0x4124u},
    {34u, 20u, 0x8000u, 0x8000u, 0x8004u, 0x811cu, 0x8124u},
};

static int mmio_valid(const os_pi5_mmio *mmio, u32 region, u32 offset)
{
    return mmio != (const os_pi5_mmio *)0
        && region < OS_DEVICE_TREE_MAX_REGIONS
        && offset <= mmio->region_sizes[region]
        && sizeof(u32) <= mmio->region_sizes[region] - offset
        && (offset & 3u) == 0;
}

static int read32(
    const os_pi5_mmio *mmio,
    u32 region,
    u32 offset,
    u32 *value
)
{
    if (value == (u32 *)0 || !mmio_valid(mmio, region, offset)
        || mmio->read32 == (os_pi5_mmio_read32)0) {
        return 0;
    }
    return mmio->read32(mmio->context, region, offset, value);
}

static int write32(os_pi5_mmio *mmio, u32 region, u32 offset, u32 value)
{
    if (!mmio_valid(mmio, region, offset)
        || mmio->write32 == (os_pi5_mmio_write32)0) {
        return 0;
    }
    return mmio->write32(mmio->context, region, offset, value);
}

static int update32(
    os_pi5_mmio *mmio,
    u32 region,
    u32 offset,
    u32 clear_mask,
    u32 set_mask
)
{
    u32 value = 0;
    return read32(mmio, region, offset, &value)
        && write32(mmio, region, offset,
            (value & ~clear_mask) | set_mask);
}

static const os_rp1_gpio_bank *find_bank(u32 pin, u32 *bank_pin)
{
    for (usize i = 0;
        i < sizeof(g_rp1_gpio_banks) / sizeof(g_rp1_gpio_banks[0]);
        ++i) {
        const os_rp1_gpio_bank *bank = &g_rp1_gpio_banks[i];
        if (pin >= bank->first_pin
            && pin - bank->first_pin < bank->pin_count) {
            *bank_pin = pin - bank->first_pin;
            return bank;
        }
    }
    return (const os_rp1_gpio_bank *)0;
}

static int gpio_valid(os_rp1_gpio *gpio, u32 pin)
{
    return gpio != (os_rp1_gpio *)0 && gpio->ready
        && pin < OS_RP1_GPIO_COUNT;
}

static int gpio_operation_enter(os_rp1_gpio *gpio)
{
    if (gpio == (os_rp1_gpio *)0) {
        return 0;
    }
    u32 state = __atomic_load_n(
        &gpio->lifecycle_state, __ATOMIC_ACQUIRE);
    if ((state & RP1_GPIO_LIFECYCLE_CLOSING) != 0u
        || (state & RP1_GPIO_LIFECYCLE_ACTIVE_MASK)
            == RP1_GPIO_LIFECYCLE_ACTIVE_MASK) {
        return 0;
    }
    u32 expected = state;
    if (!__atomic_compare_exchange_n(
            &gpio->lifecycle_state, &expected, state + 1u, 0,
            __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        return 0;
    }
    if (!gpio->ready) {
        __atomic_sub_fetch(
            &gpio->lifecycle_state, 1u, __ATOMIC_RELEASE);
        return 0;
    }
    return 1;
}

static void gpio_operation_leave(os_rp1_gpio *gpio)
{
    __atomic_sub_fetch(
        &gpio->lifecycle_state, 1u, __ATOMIC_RELEASE);
}

static int gpio_pin_lock_unowned(os_rp1_gpio *gpio, u32 pin)
{
    if (gpio == (os_rp1_gpio *)0
        || pin >= OS_RP1_GPIO_COUNT
        || !gpio_operation_enter(gpio)) {
        return 0;
    }
    u32 expected = 0u;
    if (__atomic_compare_exchange_n(
        &gpio->pin_owners[pin], &expected, OS_OWNER_RESERVED, 0,
        __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        return 1;
    }
    gpio_operation_leave(gpio);
    return 0;
}

static int gpio_pin_lock_owned(
    os_rp1_gpio *gpio,
    u32 pin,
    u32 owner
)
{
    if (gpio == (os_rp1_gpio *)0 || pin >= OS_RP1_GPIO_COUNT
        || owner == 0u || owner == OS_OWNER_RESERVED
        || !gpio_operation_enter(gpio)) {
        return 0;
    }
    u32 expected = owner;
    if (__atomic_compare_exchange_n(
        &gpio->pin_owners[pin], &expected, OS_OWNER_RESERVED, 0,
        __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        return 1;
    }
    gpio_operation_leave(gpio);
    return 0;
}

static void gpio_pin_unlock(
    os_rp1_gpio *gpio,
    u32 pin,
    u32 owner
)
{
    __atomic_store_n(&gpio->pin_owners[pin], owner, __ATOMIC_RELEASE);
    gpio_operation_leave(gpio);
}

static int uart_valid(os_pl011_uart *uart, u32 offset)
{
    return uart != (os_pl011_uart *)0 && uart->ready
        && offset <= uart->region_size
        && sizeof(u32) <= uart->region_size - offset;
}

static int spi_valid(os_dw_spi *spi, u32 offset)
{
    return spi != (os_dw_spi *)0 && spi->ready
        && offset <= spi->region_size
        && sizeof(u32) <= spi->region_size - offset;
}

static int i2c_valid(os_dw_i2c *i2c, u32 offset)
{
    return i2c != (os_dw_i2c *)0 && i2c->ready
        && offset <= i2c->region_size
        && sizeof(u32) <= i2c->region_size - offset;
}

static int configure_gpio(os_rp1_gpio *gpio, u32 pin)
{
    u32 bank_pin = 0;
    const os_rp1_gpio_bank *bank = find_bank(pin, &bank_pin);
    if (bank == (const os_rp1_gpio_bank *)0) {
        return 0;
    }
    u32 control_offset = bank->gpio_offset + bank_pin * 8u + 4u;
    u32 control_mask = 0x1fu | (3u << 12) | (3u << 14);
    u32 control_value = 5u;
    u32 pad_offset = bank->pads_offset + bank_pin * 4u;
    return update32(&gpio->mmio, 2u, pad_offset,
            1u << 7, (1u << 6))
        && update32(&gpio->mmio, 0u, control_offset,
            control_mask, control_value);
}

static int set_direction(os_rp1_gpio *gpio, u32 pin, int output)
{
    u32 bank_pin = 0;
    const os_rp1_gpio_bank *bank = find_bank(pin, &bank_pin);
    if (bank == (const os_rp1_gpio_bank *)0) {
        return 0;
    }
    u32 offset = bank->rio_offset
        + (output ? 0x2004u : 0x3004u);
    return write32(&gpio->mmio, 1u, offset, 1u << bank_pin);
}

static int gpio_set_value_locked(
    os_rp1_gpio *gpio,
    u32 pin,
    int value
)
{
    if (value != 0 && value != 1) {
        return 0;
    }
    u32 bank_pin = 0u;
    const os_rp1_gpio_bank *bank = find_bank(pin, &bank_pin);
    if (bank == (const os_rp1_gpio_bank *)0) {
        return 0;
    }
    u32 offset = bank->rio_offset
        + (value ? 0x2000u : 0x3000u);
    return write32(&gpio->mmio, 1u, offset, 1u << bank_pin);
}

static int gpio_configure_output_locked(
    os_rp1_gpio *gpio,
    u32 pin,
    int value
)
{
    return (value == 0 || value == 1)
        && configure_gpio(gpio, pin)
        && gpio_set_value_locked(gpio, pin, value)
        && set_direction(gpio, pin, 1);
}

int os_rp1_gpio_init(
    os_rp1_gpio *gpio,
    const os_device_tree_node *node,
    const os_pi5_mmio *mmio
)
{
    if (gpio == (os_rp1_gpio *)0) {
        return 0;
    }
    u32 expected_state = 0u;
    if (!__atomic_compare_exchange_n(
            &gpio->lifecycle_state, &expected_state,
            RP1_GPIO_LIFECYCLE_CLOSING, 0,
            __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        return 0;
    }
    if (gpio->ready) {
        for (u32 pin = 0u; pin < OS_RP1_GPIO_COUNT; ++pin) {
            if (__atomic_load_n(
                    &gpio->pin_owners[pin], __ATOMIC_ACQUIRE) != 0u) {
                __atomic_store_n(
                    &gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
                return 0;
            }
        }
    }
    gpio->ready = 0;
    if (node == (const os_device_tree_node *)0
        || mmio == (const os_pi5_mmio *)0
        || !node->enabled
        || node->compatible[0] == '\0'
        || node->region_count != 3u
        || node->regions[0].translated == 0
        || node->regions[1].translated == 0
        || node->regions[2].translated == 0
        || node->regions[0].size < OS_RP1_GPIO_REGION_SIZE
        || node->regions[1].size < OS_RP1_GPIO_REGION_SIZE
        || node->regions[2].size < OS_RP1_GPIO_REGION_SIZE
        || mmio->read32 == (os_pi5_mmio_read32)0
        || mmio->write32 == (os_pi5_mmio_write32)0
        || mmio->region_sizes[0] < OS_RP1_GPIO_REGION_SIZE
        || mmio->region_sizes[1] < OS_RP1_GPIO_REGION_SIZE
        || mmio->region_sizes[2] < OS_RP1_GPIO_REGION_SIZE) {
        __atomic_store_n(&gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
        return 0;
    }
    if (!expected_compatible(node, "raspberrypi,rp1-gpio")) {
        __atomic_store_n(&gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
        return 0;
    }
    gpio->mmio = *mmio;
    gpio->rp1 = (os_pi5_rp1_pci *)0;
    gpio->tree = (const os_device_tree *)0;
    gpio->node_index = OS_DEVICE_TREE_NO_PARENT;
    gpio->parent_vectors_bound = 0u;
    gpio->dispatch_error = 0u;
    for (u32 pin = 0; pin < OS_RP1_GPIO_COUNT; ++pin) {
        __atomic_store_n(&gpio->pin_owners[pin], 0u, __ATOMIC_RELAXED);
        gpio->irq_handlers[pin] = (os_pi5_interrupt_handler)0;
        gpio->irq_contexts[pin] = (void *)0;
        gpio->irq_types[pin] = 0u;
        gpio->irq_enabled[pin] = 0u;
    }
    gpio->ready = 1;
    __atomic_store_n(&gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
    return 1;
}

static int rp1_bar_contains_region(
    u64 physical_address,
    u64 mapped_size,
    const os_device_tree_region *region
)
{
    if (region == (const os_device_tree_region *)0
        || mapped_size == 0u
        || physical_address > (~(u64)0) - mapped_size
        || region->address < physical_address) {
        return 0;
    }
    u64 offset = region->address - physical_address;
    return offset <= mapped_size
        && region->size <= mapped_size - offset;
}

static int rp1_child_regions_owned_by_bar(
    os_pi5_rp1_pci *rp1,
    const os_device_tree_node *node,
    u8 region_count
)
{
    if (rp1 == (os_pi5_rp1_pci *)0 || !rp1->ready
        || node == (const os_device_tree_node *)0 || !node->enabled
        || rp1->host == (os_pi5_bcm2712_pcie_host *)0
        || rp1->host_node == (const os_device_tree_node *)0
        || rp1->active_vector_count != 0u
        || region_count == 0u || region_count > node->region_count
        || region_count > OS_DEVICE_TREE_MAX_REGIONS) {
        return 0;
    }

    for (usize region_index = 0u; region_index < region_count;
        ++region_index) {
        const os_device_tree_region *region =
            &node->regions[region_index];
        if (!region->translated || region->size < sizeof(u32)
            || region->address > (~(u64)0) - region->size) {
            return 0;
        }

        usize owners = 0u;
        for (usize bar_index = 0u; bar_index < OS_PI5_PCI_MAX_BARS;
            ++bar_index) {
            const os_pi5_pcie_bar_resource *resource =
                &rp1->bars[bar_index];
            if (!resource->active) {
                continue;
            }
            const os_pi5_pcie_bar_mapping *mapping = &resource->mapping;
            const os_pi5_pcie_allocation *allocation =
                &resource->allocation;
            if (resource->bar_index != bar_index
                || !mapping->active || !mapping->bar.implemented
                || mapping->bar.index != bar_index || mapping->bar.is_io
                || mapping->mapped_size == 0u
                || !allocation->active
                || resource->function.bus != rp1->function.bus
                || resource->function.device != rp1->function.device
                || resource->function.function != rp1->function.function
                || resource->function.vendor_id != rp1->function.vendor_id
                || resource->function.device_id != rp1->function.device_id
                || mapping->bar.base != allocation->pci_address
                || mapping->bar.size != allocation->size
                || mapping->physical_address != allocation->physical_address
                || (u64)mapping->mapped_size != allocation->size) {
                return 0;
            }
            if (rp1_bar_contains_region(
                    mapping->physical_address, mapping->mapped_size,
                    region)) {
                ++owners;
            }
        }
        if (owners != 1u) {
            return 0;
        }
    }
    return 1;
}

int os_pi5_rp1_gpio_attach(
    os_pi5_rp1_pci *rp1,
    const os_device_tree *tree,
    const os_device_tree_node *node,
    const os_pi5_mmio_mapper *mapper,
    os_pi5_mmio_mapping *mapping,
    os_rp1_gpio *gpio
)
{
    u16 node_index = OS_DEVICE_TREE_NO_PARENT;
    if (mapping == (os_pi5_mmio_mapping *)0
        || gpio == (os_rp1_gpio *)0 || gpio->ready
        || __atomic_load_n(
            &gpio->lifecycle_state, __ATOMIC_ACQUIRE) != 0u) {
        return 0;
    }
    if (mapping->mapped_region_count != 0u
        || mapping->mapper.map_region != (os_pi5_mmio_map_region)0
        || mapping->mmio.read32 != (os_pi5_mmio_read32)0
        || mapping->mmio.write32 != (os_pi5_mmio_write32)0
        || !rp1_child_node_valid(rp1, tree, node)
        || !rp1_child_regions_owned_by_bar(
            rp1, node, node->region_count)
        || !device_tree_node_index(tree, node, &node_index)
        || !expected_compatible(node, "raspberrypi,rp1-gpio")
        || node->region_count != 3u) {
        return 0;
    }
    gpio->ready = 0u;
    if (!os_pi5_mmio_map_init(mapping, node, mapper)) {
        return 0;
    }
    if (!os_rp1_gpio_init(gpio, node, &mapping->mmio)) {
        os_pi5_mmio_unmap(mapping);
        return 0;
    }
    gpio->node_index = node_index;
    gpio->tree = tree;
    return 1;
}

int os_pi5_rp1_gpio_cleanup(
    os_pi5_mmio_mapping *mapping,
    os_rp1_gpio *gpio
)
{
    if (mapping == (os_pi5_mmio_mapping *)0
        || gpio == (os_rp1_gpio *)0
        || mapping->mapped_region_count != 3u) {
        return 0;
    }
    u32 expected_state = 0u;
    if (!__atomic_compare_exchange_n(
            &gpio->lifecycle_state, &expected_state,
            RP1_GPIO_LIFECYCLE_CLOSING, 0,
            __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        return 0;
    }
    if (!gpio->ready) {
        __atomic_store_n(&gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
        return 0;
    }
    for (u32 pin = 0u; pin < OS_RP1_GPIO_COUNT; ++pin) {
        if (__atomic_load_n(
                &gpio->pin_owners[pin], __ATOMIC_ACQUIRE) != 0u) {
            __atomic_store_n(
                &gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
            return 0;
        }
    }
    for (u32 pin = 0; pin < OS_RP1_GPIO_COUNT; ++pin) {
        if (gpio->irq_enabled[pin]
            && !rp1_gpio_irq_enable_locked(gpio, pin, 0)) {
            __atomic_store_n(
                &gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
            return 0;
        }
    }
    if (gpio->rp1 != (os_pi5_rp1_pci *)0) {
        for (u32 bank = OS_RP1_GPIO_INTERRUPT_PARENT_COUNT;
            bank != 0u; --bank) {
            u32 vector = bank - 1u;
            if ((gpio->parent_vectors_bound & (1u << vector)) != 0u) {
                if (!os_pi5_rp1_pci_msix_unbind(
                        gpio->rp1, vector)) {
                    __atomic_store_n(
                        &gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
                    return 0;
                }
                gpio->parent_vectors_bound &= (u8)~(1u << vector);
            }
        }
    }
    for (u32 pin = 0; pin < OS_RP1_GPIO_COUNT; ++pin) {
        gpio->irq_handlers[pin] = (os_pi5_interrupt_handler)0;
        gpio->irq_contexts[pin] = (void *)0;
        gpio->irq_types[pin] = 0u;
    }
    gpio->rp1 = (os_pi5_rp1_pci *)0;
    gpio->tree = (const os_device_tree *)0;
    gpio->node_index = OS_DEVICE_TREE_NO_PARENT;
    gpio->ready = 0u;
    os_pi5_mmio_unmap(mapping);
    int unmapped = mapping->mapped_region_count == 0u;
    __atomic_store_n(&gpio->lifecycle_state, 0u, __ATOMIC_RELEASE);
    return unmapped;
}

