static int bcm2712_hdmi_firmware_clock_restore(
    const os_pi5_bcm2712_hdmi_dvp_lease *dvp_lease,
    const os_pi5_bcm2712_hdmi_clock_state original[2],
    os_pi5_bcm2712_firmware_property_request query_request,
    os_pi5_bcm2712_firmware_property_request set_request,
    void *property_context
)
{
    if (dvp_lease == (const os_pi5_bcm2712_hdmi_dvp_lease *)0
        || original == (const os_pi5_bcm2712_hdmi_clock_state *)0) {
        return 0;
    }
    u8 port = (dvp_lease->port_mask & 1u) != 0u ? 0u : 1u;
    os_pi5_bcm2712_hdmi_clock_state observed[2];
    if (!os_pi5_bcm2712_hdmi_firmware_clocks_query(
            dvp_lease->resources, port, query_request,
            property_context, observed)) {
        return 0;
    }
    for (usize i = 0u; i < 2u; ++i) {
        if (observed[i].state != original[i].state) {
            return 0;
        }
        if (observed[i].rate_hz != original[i].rate_hz) {
            (void)bcm2712_hdmi_firmware_clock_set_rate(
                set_request, property_context,
                original[i].clock_id, original[i].rate_hz);
        }
    }
    if (!os_pi5_bcm2712_hdmi_firmware_clocks_query(
            dvp_lease->resources, port, query_request,
            property_context, observed)) {
        return 0;
    }
    for (usize i = 0u; i < 2u; ++i) {
        if (observed[i].clock_id != original[i].clock_id
            || observed[i].state != original[i].state
            || observed[i].rate_hz != original[i].rate_hz) {
            return 0;
        }
    }
    return 1;
}

