    usize context_size = capabilities->context_size_bytes;
    usize input_context_size =
        OS_PI5_XHCI_INPUT_CONTEXT_ENTRIES * context_size;
    usize device_context_size =
        OS_PI5_XHCI_DEVICE_CONTEXT_ENTRIES * context_size;
