    xhci_dma_buffer_clear(&context->input_context);
    xhci_dma_buffer_clear(&context->device_context);
    u32 *input_words = (u32 *)context->input_context.virtual_address;
    u32 context_words = (u32)(context_size / sizeof(u32));
    input_words[1] =
        OS_PI5_XHCI_INPUT_CONTEXT_ADD_SLOT
        | OS_PI5_XHCI_INPUT_CONTEXT_ADD_EP0;
