    *endpoint_info =
        ((u32)interval << OS_PI5_XHCI_EP_CONTEXT_INTERVAL_SHIFT)
        | ((max_esit_payload >> 16)
            << OS_PI5_XHCI_EP_CONTEXT_MAX_ESIT_PAYLOAD_HI_SHIFT);
