static int xhci_ep0_packet_size_valid(
    u8 speed,
    u16 max_packet_size
)
{
    switch (speed) {
    case OS_PI5_XHCI_SPEED_LOW:
        return max_packet_size == 8u;
    case OS_PI5_XHCI_SPEED_FULL:
        return max_packet_size == 8u || max_packet_size == 16u
            || max_packet_size == 32u || max_packet_size == 64u;
    case OS_PI5_XHCI_SPEED_HIGH:
        return max_packet_size == 64u;
    case OS_PI5_XHCI_SPEED_SUPER:
    case OS_PI5_XHCI_SPEED_SUPER_PLUS:
        return max_packet_size == 512u;
    default:
        return 0;
    }
}

