    state->allocator = (const os_pi5_dma_allocator *)0;
    state->resources = (os_pi5_rp1_dwc3_resources *)0;
    state->capabilities = (os_pi5_xhci_capabilities){0};
    state->rings = (os_pi5_xhci_dma_rings *)0;
    state->event_handler = (os_pi5_xhci_event_handler)0;
    state->event_context = (void *)0;
    state->event_budget = 0u;
    state->events_processed = 0u;
    state->interrupt_vector = 0u;
    state->last_result = OS_PI5_XHCI_EVENT_ERROR;
    state->ready = 0u;
    state->more_pending = 0u;
    state->dispatch_error = 0u;
    state->dispatch_active = 0u;

    if (allocator == (const os_pi5_dma_allocator *)0
        || resources == (os_pi5_rp1_dwc3_resources *)0
        || rings == (os_pi5_xhci_dma_rings *)0
        || event_handler == (os_pi5_xhci_event_handler)0
        || event_budget == 0u
        || event_budget > OS_PI5_XHCI_EVENT_MAX_BUDGET
        || resources->rp1 == (os_pi5_rp1_pci *)0
        || !resources->rp1->ready
        || resources->interrupt.interrupt_id
            >= OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT) {
        return 0;
    }

    u32 missing_prerequisites = 0u;
    os_pi5_xhci_capabilities capabilities = {0};
    if (!os_pi5_rp1_dwc3_startup_prerequisites_check(
            resources, rings, checks, poll_limit,
            &missing_prerequisites)
        || missing_prerequisites != 0u
        || !os_pi5_rp1_xhci_capabilities_read(
            resources, &capabilities)) {
        return 0;
    }

    state->allocator = allocator;
    state->resources = resources;
    state->capabilities = capabilities;
    state->rings = rings;
    state->event_handler = event_handler;
    state->event_context = event_context;
    state->event_budget = event_budget;
    state->interrupt_vector = resources->interrupt.interrupt_id;
    state->last_result = OS_PI5_XHCI_EVENT_EMPTY;
