    os_pi5_rp1_dwc3_resources *resources =
        state != (const os_pi5_xhci_msix_dispatch_state *)0
            ? state->resources
            : (os_pi5_rp1_dwc3_resources *)0;
    const os_pi5_xhci_dma_rings *rings =
        state != (const os_pi5_xhci_msix_dispatch_state *)0
            ? state->rings
            : (const os_pi5_xhci_dma_rings *)0;
    return os_pi5_rp1_dwc3_startup_prerequisites_check(
        resources, rings, &checks, poll_limit, missing_prerequisites);
