    if ((endpoint->max_packet_size & 0x07ffu) < report_length) {
        return 0;
    }

    u32 endpoint_number = endpoint->address & 0x0fu;
    if (endpoint_number == 0u) {
        return 0;
    }
    u32 endpoint_id = endpoint_number * 2u + 1u;
    u32 endpoint_mask = 1u << endpoint_id;
