    context->hid_input_pending_mask &= ~endpoint_mask;
    context->hid_input_completion_trb_addresses[endpoint_id] = 0u;
    context->hid_input_report_lengths[endpoint_id] = 0u;
    context->hid_input_endpoint_indices[endpoint_id] = 0u;
