    context->usb_bot_recovery_completion_code = 0u;
    ++context->usb_bot_tag;
    if (context->usb_bot_tag == 0u) {
        ++context->usb_bot_tag;
    }

    u8 *cbw = (u8 *)context->usb_bot_cbw_buffer.virtual_address;
