int os_pi5_bcm2712_wlan_resources_discover(
    const os_device_tree *tree,
    usize sdhci_node_index,
    usize wifi_node_index,
    os_pi5_bcm2712_wlan_resources *resources
)
{
    if (resources != (os_pi5_bcm2712_wlan_resources *)0) {
        os_pi5_bcm2712_wlan_resources_init_state(resources);
    }
    if (tree == (const os_device_tree *)0
        || tree->node_count == 0u
        || tree->node_count > OS_DEVICE_TREE_MAX_NODES
        || sdhci_node_index >= tree->node_count
        || wifi_node_index >= tree->node_count
        || resources == (os_pi5_bcm2712_wlan_resources *)0) {
        return 0;
    }

    const os_device_tree_node *host = &tree->nodes[sdhci_node_index];
    const os_device_tree_node *wifi = &tree->nodes[wifi_node_index];
    if (!host->enabled
        || !expected_compatible(host, "brcm,bcm2712-sdhci")
        || host->region_count != 2u
        || !host->regions[0].translated
        || !host->regions[1].translated
        || host->regions[0].size != OS_BCM2712_SDHCI_HOST_REGION_SIZE
        || host->regions[1].size
            != OS_BCM2712_SDHCI_CONFIG_REGION_SIZE
        || host->regions[0].address
            > (~(u64)0) - host->regions[0].size
        || host->regions[1].address
            > (~(u64)0) - host->regions[1].size
        || (host->regions[0].address
                < host->regions[1].address + host->regions[1].size
            && host->regions[1].address
                < host->regions[0].address + host->regions[0].size)
        || host->clock_reference_count != 1u
        || !host->bus_width_present || host->bus_width != 4u
        || !host->non_removable
        || !host->vmmc_supply_present
        || host->vmmc_supply_index >= tree->node_count
        || wifi->parent_index != sdhci_node_index
        || !wifi->enabled
        || !expected_compatible(wifi, "brcm,bcm4329-fmac")
        || wifi->region_count != 1u
        || wifi->regions[0].address != 1u
        || wifi->regions[0].size != 0u) {
        return 0;
    }

    u32 clock_hz = 0u;
    os_device_tree_gic_interrupt interrupt;
    if (!os_device_tree_get_clock_frequency(
            tree, host, 0u, &clock_hz)
        || clock_hz != OS_BCM2712_SDHCI_CLOCK_HZ
        || !os_device_tree_get_gic_interrupt(
            tree, host, 0u, &interrupt)
        || !interrupt.is_peripheral
        || interrupt.interrupt_id
            != OS_BCM2712_SDIO2_GIC_INTERRUPT_ID
        || interrupt.flags != 4u) {
        return 0;
    }

    u16 supply_index = host->vmmc_supply_index;
    const os_device_tree_node *supply = &tree->nodes[supply_index];
    if (!supply->enabled
        || !expected_compatible(supply, "regulator-fixed")
        || !supply->regulator_min_present
        || !supply->regulator_max_present
        || supply->regulator_min_microvolt != 3300000u
        || supply->regulator_max_microvolt != 3300000u
        || !supply->regulator_enable_active_high
        || !supply->regulator_startup_delay_present
        || supply->regulator_startup_delay_us
            != OS_BCM2712_WLAN_STARTUP_DELAY_US
        || !supply->regulator_gpio_resolved
        || supply->regulator_gpio_cell_count != 3u
        || supply->regulator_gpio_flags != 0u
        || supply->regulator_gpio_provider_index >= tree->node_count) {
        return 0;
    }
    u16 gpio_index = supply->regulator_gpio_provider_index;
    const os_device_tree_node *gpio = &tree->nodes[gpio_index];
    if (!gpio->enabled
        || !expected_compatible(gpio, "raspberrypi,rp1-gpio")
        || !gpio->gpio_specifier_cells_present
        || gpio->gpio_specifier_cells != 2u
        || supply->regulator_gpio_pin != OS_BCM2712_WLAN_GPIO_PIN
        || !bcm2712_wlan_gpio_has_rp1_ancestor(tree, gpio_index)) {
        return 0;
    }

    resources->interrupt = interrupt;
    resources->clock_hz = clock_hz;
    resources->supply_microvolt = 3300000u;
    resources->supply_startup_delay_us =
        supply->regulator_startup_delay_us;
    resources->supply_gpio_pin = supply->regulator_gpio_pin;
    resources->supply_gpio_flags = supply->regulator_gpio_flags;
    resources->sdhci_node_index = (u16)sdhci_node_index;
    resources->wifi_node_index = (u16)wifi_node_index;
    resources->supply_node_index = supply_index;
    resources->gpio_provider_index = gpio_index;
    resources->bus_width = host->bus_width;
    resources->function_number = (u8)wifi->regions[0].address;
    resources->ready = 1u;
    return 1;
}

