static int bcm2712_sd_pinctrl_verify_registers(
    const os_pi5_bcm2712_sd_pinctrl *pinctrl
)
{
    static const u8 c0_pad_shifts[5] = { 2u, 8u, 10u, 12u, 14u };
    static const u8 d0_pad_shifts[5] = { 6u, 12u, 14u, 16u, 18u };
    u32 mux = 0u;
    u32 aon_pad = 0u;
    u32 emmc_pad = 0u;
    u32 mux_functions[3];
    u8 pad_offset;
    u8 aon_pad_offset;
    const u8 *pad_shifts;
    if (pinctrl->silicon_revision == OS_BCM2712_SD_PINCTRL_REV_C0) {
        mux_functions[0] = 6u;
        mux_functions[1] = 7u;
        mux_functions[2] = 6u;
        pad_offset = OS_BCM2712_SD_PINCTRL_C0_PAD_OFFSET;
        aon_pad_offset = OS_BCM2712_SD_PINCTRL_C0_AON_PAD_OFFSET;
        pad_shifts = c0_pad_shifts;
    } else if (pinctrl->silicon_revision
        == OS_BCM2712_SD_PINCTRL_REV_D0) {
        mux_functions[0] = 5u;
        mux_functions[1] = 5u;
        mux_functions[2] = 4u;
        pad_offset = OS_BCM2712_SD_PINCTRL_D0_PAD_OFFSET;
        aon_pad_offset = OS_BCM2712_SD_PINCTRL_D0_AON_PAD_OFFSET;
        pad_shifts = d0_pad_shifts;
    } else {
        return 0;
    }
    if (!read32(
            &pinctrl->aon_pinctrl_mmio, 0u,
            OS_BCM2712_SD_PINCTRL_AON_MUX_OFFSET, &mux)
        || !read32(
            &pinctrl->aon_pinctrl_mmio, 0u,
            aon_pad_offset, &aon_pad)
        || !read32(
            &pinctrl->pinctrl_mmio, 0u, pad_offset, &emmc_pad)) {
        return 0;
    }
    for (u32 pin = 0u; pin < 3u; ++pin) {
        u32 shift = 12u + pin * 4u;
        if (((mux >> shift) & 0x0fu) != mux_functions[pin]) {
            return 0;
        }
    }
    if (((aon_pad >> (pinctrl->silicon_revision
                == OS_BCM2712_SD_PINCTRL_REV_C0 ? 0u : 28u))
            & 3u) != 2u) {
        return 0;
    }
    for (u32 i = 0u; i < 5u; ++i) {
        if (((emmc_pad >> pad_shifts[i]) & 3u) != 2u) {
            return 0;
        }
    }
    return 1;
}

int os_pi5_bcm2712_sd_pinctrl_attach(
    const os_device_tree *tree,
    const os_device_tree_node *sdhci_node,
    const os_pi5_mmio_mapper *mapper,
    os_pi5_mmio_mapping *pinctrl_mapping,
    os_pi5_mmio_mapping *aon_pinctrl_mapping,
    os_pi5_bcm2712_sd_pinctrl *pinctrl
)
{
    if (tree == (const os_device_tree *)0
        || tree->node_count == 0u
        || tree->node_count > OS_DEVICE_TREE_MAX_NODES
        || sdhci_node == (const os_device_tree_node *)0
        || mapper == (const os_pi5_mmio_mapper *)0
        || mapper->map_region == (os_pi5_mmio_map_region)0
        || mapper->unmap_region == (os_pi5_mmio_unmap_region)0
        || !bcm2712_sd_pinctrl_mapping_empty(pinctrl_mapping)
        || !bcm2712_sd_pinctrl_mapping_empty(aon_pinctrl_mapping)
        || pinctrl == (os_pi5_bcm2712_sd_pinctrl *)0
        || pinctrl->ready) {
        return 0;
    }
    os_pi5_bcm2712_sd_pinctrl_init_state(pinctrl);
    u16 sdhci_index = 0u;
    if (!device_tree_node_index(tree, sdhci_node, &sdhci_index)
        || sdhci_index >= tree->node_count
        || !sdhci_node->enabled
        || !expected_compatible(sdhci_node, "brcm,bcm2712-sdhci")
        || sdhci_node->parent_index >= tree->node_count) {
        return 0;
    }

    const os_device_tree_node *main_node =
        (const os_device_tree_node *)0;
    const os_device_tree_node *aon_node =
        (const os_device_tree_node *)0;
    u8 revision = 0u;
    for (usize i = 0u; i < tree->node_count; ++i) {
        const os_device_tree_node *candidate = &tree->nodes[i];
        u8 candidate_revision = 0u;
        int is_main = 0;
        int is_aon = 0;
        if (expected_compatible(
                candidate, "brcm,bcm2712c0-pinctrl")) {
            candidate_revision = OS_BCM2712_SD_PINCTRL_REV_C0;
            is_main = 1;
        } else if (expected_compatible(
                candidate, "brcm,bcm2712d0-pinctrl")) {
            candidate_revision = OS_BCM2712_SD_PINCTRL_REV_D0;
            is_main = 1;
        } else if (expected_compatible(
                candidate, "brcm,bcm2712c0-aon-pinctrl")) {
            candidate_revision = OS_BCM2712_SD_PINCTRL_REV_C0;
            is_aon = 1;
        } else if (expected_compatible(
                candidate, "brcm,bcm2712d0-aon-pinctrl")) {
            candidate_revision = OS_BCM2712_SD_PINCTRL_REV_D0;
            is_aon = 1;
        } else {
            continue;
        }
        if (!candidate->enabled
            || candidate->parent_index != sdhci_node->parent_index
            || (revision != 0u && revision != candidate_revision)) {
            return 0;
        }
        revision = candidate_revision;
        if (is_main) {
            if (main_node != (const os_device_tree_node *)0) {
                return 0;
            }
            main_node = candidate;
        }
        if (is_aon) {
            if (aon_node != (const os_device_tree_node *)0) {
                return 0;
            }
            aon_node = candidate;
        }
    }
    if (main_node == (const os_device_tree_node *)0
        || aon_node == (const os_device_tree_node *)0
        || revision == 0u
        || !tree->nodes[sdhci_node->parent_index].enabled
        || !expected_compatible(
            &tree->nodes[sdhci_node->parent_index], "simple-bus")) {
        return 0;
    }
    u64 main_address = 0x7d504100ull;
    u64 main_size = revision == OS_BCM2712_SD_PINCTRL_REV_C0
        ? 0x30ull : 0x20ull;
    u64 aon_size = revision == OS_BCM2712_SD_PINCTRL_REV_C0
        ? 0x20ull : 0x1cull;
    if (main_node->region_count != 1u
        || !main_node->regions[0].translated
        || main_node->regions[0].address != main_address
        || main_node->regions[0].size != main_size
        || aon_node->region_count != 1u
        || !aon_node->regions[0].translated
        || aon_node->regions[0].address != 0x7d510700ull
        || aon_node->regions[0].size != aon_size) {
        return 0;
    }
    if (!os_pi5_mmio_map_init_regions(
            pinctrl_mapping, main_node, mapper, 1u)) {
        return 0;
    }
    if (!os_pi5_mmio_map_init_regions(
            aon_pinctrl_mapping, aon_node, mapper, 1u)) {
        os_pi5_mmio_unmap(pinctrl_mapping);
        return 0;
    }
    pinctrl->pinctrl_mmio = pinctrl_mapping->mmio;
    pinctrl->aon_pinctrl_mmio = aon_pinctrl_mapping->mmio;
    pinctrl->pinctrl_mapping = pinctrl_mapping;
    pinctrl->aon_pinctrl_mapping = aon_pinctrl_mapping;
    pinctrl->silicon_revision = revision;
    if (!bcm2712_sd_pinctrl_verify_registers(pinctrl)) {
        os_pi5_mmio_unmap(aon_pinctrl_mapping);
        os_pi5_mmio_unmap(pinctrl_mapping);
        os_pi5_bcm2712_sd_pinctrl_init_state(pinctrl);
        return 0;
    }
    pinctrl->ready = 1u;
    return 1;
}

int os_pi5_bcm2712_sd_pinctrl_verify(
    const os_pi5_bcm2712_sd_pinctrl *pinctrl
)
{
    if (pinctrl == (const os_pi5_bcm2712_sd_pinctrl *)0
        || !pinctrl->ready
        || pinctrl->pinctrl_mapping
            == (os_pi5_mmio_mapping *)0
        || pinctrl->aon_pinctrl_mapping
            == (os_pi5_mmio_mapping *)0
        || pinctrl->pinctrl_mapping->mapped_region_count != 1u
        || pinctrl->aon_pinctrl_mapping->mapped_region_count != 1u
        || pinctrl->pinctrl_mapping->mmio.context
            != pinctrl->pinctrl_mmio.context
        || pinctrl->pinctrl_mapping->mmio.read32
            != pinctrl->pinctrl_mmio.read32
        || pinctrl->aon_pinctrl_mapping->mmio.context
            != pinctrl->aon_pinctrl_mmio.context
        || pinctrl->aon_pinctrl_mapping->mmio.read32
            != pinctrl->aon_pinctrl_mmio.read32) {
        return 0;
    }
    return bcm2712_sd_pinctrl_verify_registers(pinctrl);
}

int os_pi5_bcm2712_sd_pinctrl_cleanup(
    os_pi5_mmio_mapping *pinctrl_mapping,
    os_pi5_mmio_mapping *aon_pinctrl_mapping,
    os_pi5_bcm2712_sd_pinctrl *pinctrl
)
{
    if (pinctrl_mapping == (os_pi5_mmio_mapping *)0
        || aon_pinctrl_mapping == (os_pi5_mmio_mapping *)0
        || pinctrl == (os_pi5_bcm2712_sd_pinctrl *)0
        || !pinctrl->ready
        || pinctrl->pinctrl_mapping != pinctrl_mapping
        || pinctrl->aon_pinctrl_mapping != aon_pinctrl_mapping
        || pinctrl_mapping->mapped_region_count != 1u
        || aon_pinctrl_mapping->mapped_region_count != 1u
        || pinctrl_mapping->mmio.context
            != pinctrl->pinctrl_mmio.context
        || pinctrl_mapping->mmio.read32
            != pinctrl->pinctrl_mmio.read32
        || aon_pinctrl_mapping->mmio.context
            != pinctrl->aon_pinctrl_mmio.context
        || aon_pinctrl_mapping->mmio.read32
            != pinctrl->aon_pinctrl_mmio.read32) {
        return 0;
    }
    os_pi5_mmio_unmap(aon_pinctrl_mapping);
    os_pi5_mmio_unmap(pinctrl_mapping);
    os_pi5_bcm2712_sd_pinctrl_init_state(pinctrl);
    return pinctrl_mapping->mapped_region_count == 0u
        && aon_pinctrl_mapping->mapped_region_count == 0u;
}

static int bcm2712_sd_gpio_set_bits(
    os_pi5_bcm2712_sd_gpio_supply *supply,
    u32 data_bits,
    u32 direction_bits
)
{
    u32 current_data = 0u;
    u32 current_direction = 0u;
    if (!read32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DATA_OFFSET, &current_data)
        || !read32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DIRECTION_OFFSET, &current_direction)) {
        return 0;
    }
    u32 next_data = (current_data & ~supply->gpio_mask)
        | (data_bits & supply->gpio_mask);
    u32 next_direction = (current_direction & ~supply->gpio_mask)
        | (direction_bits & supply->gpio_mask);
    if (!write32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DATA_OFFSET, next_data)
        || !write32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DIRECTION_OFFSET, next_direction)
        || !read32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DATA_OFFSET, &current_data)
        || !read32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DIRECTION_OFFSET, &current_direction)) {
        return 0;
    }
    return (current_data & supply->gpio_mask)
            == (data_bits & supply->gpio_mask)
        && (current_direction & supply->gpio_mask)
            == (direction_bits & supply->gpio_mask);
}

static int bcm2712_sd_gpio_restore(
    os_pi5_bcm2712_sd_gpio_supply *supply
)
{
    return !supply->state_saved
        || bcm2712_sd_gpio_set_bits(
            supply, supply->original_data_bits,
            supply->original_direction_bits);
}

int os_pi5_bcm2712_sd_gpio_supply_control(
    void *context,
    u32 card_supply_uv,
    u32 io_supply_uv,
    int enabled
)
{
    os_pi5_bcm2712_sd_gpio_supply *supply =
        (os_pi5_bcm2712_sd_gpio_supply *)context;
    if (supply == (os_pi5_bcm2712_sd_gpio_supply *)0
        || !supply->ready || supply->faulted
        || (enabled != 0 && enabled != 1)
        || card_supply_uv != 3300000u
        || io_supply_uv != 3300000u
        || (enabled && supply->active)) {
        return 0;
    }
    if (!enabled && !supply->state_saved) {
        return 1;
    }
    if (!supply->state_saved) {
        u32 data = 0u;
        u32 direction = 0u;
        if (!read32(
                &supply->mmio, 0u,
                OS_BCM2712_AON_GPIO_DATA_OFFSET, &data)
            || !read32(
                &supply->mmio, 0u,
                OS_BCM2712_AON_GPIO_DIRECTION_OFFSET, &direction)) {
            return 0;
        }
        supply->original_data_bits = data & supply->gpio_mask;
        supply->original_direction_bits =
            direction & supply->gpio_mask;
        supply->state_saved = 1u;
    }
    if (!enabled && !supply->active) {
        if (!bcm2712_sd_gpio_restore(supply)) {
            supply->faulted = 1u;
            return 0;
        }
        return 1;
    }
    u32 data_bits = enabled ? (1u << 4) : 0u;
    if (!bcm2712_sd_gpio_set_bits(supply, data_bits, 0u)) {
        if (!bcm2712_sd_gpio_restore(supply)) {
            supply->faulted = 1u;
        }
        supply->active = 0u;
        return 0;
    }
    supply->active = (u8)enabled;
    return 1;
}

int os_pi5_bcm2712_sd_gpio_card_present(
    os_pi5_bcm2712_sd_gpio_supply *supply,
    int *card_present
)
{
    if (card_present != (int *)0) {
        *card_present = 0;
    }
    if (supply == (os_pi5_bcm2712_sd_gpio_supply *)0
        || !supply->ready || supply->faulted
        || supply->card_detect_mask != (1u << 5)
        || !supply->card_detect_active_low
        || card_present == (int *)0) {
        return 0;
    }
    u32 data = 0u;
    u32 direction = 0u;
    if (!read32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DATA_OFFSET, &data)
        || !read32(
            &supply->mmio, 0u,
            OS_BCM2712_AON_GPIO_DIRECTION_OFFSET, &direction)
        || (direction & supply->card_detect_mask) == 0u) {
        return 0;
    }
    *card_present = (data & supply->card_detect_mask) == 0u;
    return 1;
}

int os_pi5_bcm2712_sd_gpio_supply_cleanup(
    os_pi5_mmio_mapping *mapping,
    os_pi5_bcm2712_sd_gpio_supply *supply
)
{
    if (mapping == (os_pi5_mmio_mapping *)0
        || supply == (os_pi5_bcm2712_sd_gpio_supply *)0
        || !supply->ready || supply->active
        || mapping->mapped_region_count != 1u
        || supply->mmio.read32 == (os_pi5_mmio_read32)0
        || supply->mmio.write32 == (os_pi5_mmio_write32)0) {
        return 0;
    }
    if (!bcm2712_sd_gpio_restore(supply)) {
        supply->faulted = 1u;
        return 0;
    }
    os_pi5_mmio_unmap(mapping);
    os_pi5_bcm2712_sd_gpio_supply_init_state(supply);
    return mapping->mapped_region_count == 0u;
}

static int bcm2712_sdhci_init_clock_value(
    u32 input_clock_hz,
    u16 spec_version,
    u16 *clock_control,
    u32 *actual_clock_hz
)
{
    if (input_clock_hz == 0u || spec_version > 5u
        || clock_control == (u16 *)0
        || actual_clock_hz == (u32 *)0) {
        return 0;
    }
    u32 divisor = 1u;
    if (spec_version >= 2u) {
        u64 numerator = (u64)input_clock_hz;
        u64 denominator =
            2u * (u64)OS_BCM2712_SDHCI_INIT_CLOCK_HZ;
        u64 rounded = (numerator + denominator - 1u) / denominator;
        if (rounded == 0u || rounded > 0x3ffu) {
            return 0;
        }
        divisor = (u32)rounded;
    } else {
        while (input_clock_hz / (2u * divisor)
                > OS_BCM2712_SDHCI_INIT_CLOCK_HZ
            && divisor < 256u) {
            divisor <<= 1;
        }
        if (input_clock_hz / (2u * divisor)
            > OS_BCM2712_SDHCI_INIT_CLOCK_HZ) {
            return 0;
        }
    }
    *clock_control = (u16)(
        ((divisor & 0xffu) << 8)
        | ((divisor & 0x300u) >> 2)
        | 0x0001u);
    *actual_clock_hz = input_clock_hz / (2u * divisor);
    return *actual_clock_hz != 0u
        && *actual_clock_hz <= OS_BCM2712_SDHCI_INIT_CLOCK_HZ;
}

int os_pi5_bcm2712_sdhci_start_init_clock(
    os_pi5_bcm2712_sdhci_resources *resources,
    u32 poll_limit,
    u32 *actual_clock_hz
)
{
    if (actual_clock_hz != (u32 *)0) {
        *actual_clock_hz = 0u;
    }
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || !resources->ready || resources->clock_active
        || !resources->power_active || !resources->controller_reset
        || poll_limit == 0u
        || poll_limit > OS_BCM2712_SDHCI_MAX_POLL_LIMIT
        || actual_clock_hz == (u32 *)0
        || resources->mmio.read32 == (os_pi5_mmio_read32)0
        || resources->mmio.write32 == (os_pi5_mmio_write32)0
        || resources->mmio.read16 == (os_pi5_mmio_read16)0
        || resources->mmio.write16 == (os_pi5_mmio_write16)0
        || resources->mmio.region_sizes[0] < 0x100u
        || resources->mmio.region_sizes[1] < 0x48u) {
        return 0;
    }
    u32 pin_select = 0u;
    u16 host_version = 0u;
    u16 previous_clock = 0u;
    u16 init_clock = 0u;
    u32 init_clock_hz = 0u;
    if (!resources->mmio.read32(
            resources->mmio.context, 1u, 0x44u, &pin_select)
        || !resources->mmio.read16(
            resources->mmio.context, 0u, 0xfeu, &host_version)
        || !resources->mmio.read16(
            resources->mmio.context, 0u, 0x2cu, &previous_clock)
        || !bcm2712_sdhci_init_clock_value(
            resources->clock_hz, host_version & 0xffu,
            &init_clock, &init_clock_hz)) {
        return 0;
    }
    u32 selected_pin = (pin_select & ~3u) | 2u;
    resources->original_pin_select = pin_select;
    resources->original_clock_control =
        (u16)(previous_clock & ~0x0002u);
    resources->clock_active = 1u;
    if (!resources->mmio.write32(
            resources->mmio.context, 1u, 0x44u, selected_pin)
        || !resources->mmio.write16(
            resources->mmio.context, 0u, 0x2cu, 0u)
        || !resources->mmio.write16(
            resources->mmio.context, 0u, 0x2cu, init_clock)) {
        (void)os_pi5_bcm2712_sdhci_stop_init_clock(resources);
        return 0;
    }
    int stable = 0;
    for (u32 attempt = 0; attempt < poll_limit; ++attempt) {
        u16 value = 0u;
        if (!resources->mmio.read16(
                resources->mmio.context, 0u, 0x2cu, &value)) {
            break;
        }
        if ((value & 0x0002u) != 0u) {
            stable = 1;
            break;
        }
    }
    if (!stable
        || !resources->mmio.write16(
            resources->mmio.context, 0u, 0x2cu,
            (u16)(init_clock | 0x0004u))) {
        (void)os_pi5_bcm2712_sdhci_stop_init_clock(resources);
        return 0;
    }
    *actual_clock_hz = init_clock_hz;
    return 1;
}

int os_pi5_bcm2712_sdhci_stop_init_clock(
    os_pi5_bcm2712_sdhci_resources *resources
)
{
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || !resources->ready || !resources->clock_active
        || resources->mmio.write16 == (os_pi5_mmio_write16)0
        || resources->mmio.write32 == (os_pi5_mmio_write32)0) {
        return 0;
    }
    if (!resources->mmio.write16(
            resources->mmio.context, 0u, 0x2cu, 0u)
        || !resources->mmio.write32(
            resources->mmio.context, 1u, 0x44u,
            resources->original_pin_select)
        || !resources->mmio.write16(
            resources->mmio.context, 0u, 0x2cu,
            resources->original_clock_control)) {
        return 0;
    }
    resources->clock_active = 0u;
    resources->original_pin_select = 0u;
    resources->original_clock_control = 0u;
    return 1;
}

int os_pi5_bcm2712_sdhci_send_command(
    os_pi5_bcm2712_sdhci_resources *resources,
    u8 command_index,
    u32 argument,
    u8 command_flags,
    u32 poll_limit,
    os_pi5_delay_us delay_us,
    void *delay_context,
    u32 response[4]
)
{
    if (response != (u32 *)0) {
        for (usize i = 0; i < 4u; ++i) {
            response[i] = 0u;
        }
    }
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || !resources->ready || !resources->controller_reset
        || !resources->power_active || !resources->clock_active
        || command_index > 63u
        || (command_flags & (u8)~0x3bu) != 0u
        || poll_limit == 0u
        || poll_limit > OS_BCM2712_SDHCI_MAX_POLL_LIMIT
        || delay_us == (os_pi5_delay_us)0
        || ((command_flags & 0x03u) != OS_BCM2712_SDHCI_CMD_RESP_NONE
            && response == (u32 *)0)
        || resources->mmio.read16 == (os_pi5_mmio_read16)0
        || resources->mmio.write16 == (os_pi5_mmio_write16)0
        || resources->mmio.read32 == (os_pi5_mmio_read32)0
        || resources->mmio.write32 == (os_pi5_mmio_write32)0) {
        return 0;
    }
    u32 inhibit_mask = OS_BCM2712_SDHCI_CMD_INHIBIT;
    if ((command_flags & OS_BCM2712_SDHCI_CMD_DATA) != 0u
        || (command_flags & 0x03u)
            == OS_BCM2712_SDHCI_CMD_RESP_SHORT_BUSY) {
        inhibit_mask |= OS_BCM2712_SDHCI_DATA_INHIBIT;
    }
    int inhibit_cleared = 0;
    for (u32 poll = 0; poll < poll_limit; ++poll) {
        u32 present_state = 0u;
        if (!read32(
                &resources->mmio, 0u,
                OS_BCM2712_SDHCI_PRESENT_STATE, &present_state)) {
            return 0;
        }
        if ((present_state & inhibit_mask) == 0u) {
            inhibit_cleared = 1;
            break;
        }
        if (!delay_us(delay_context, 10u, 10u)) {
            return 0;
        }
    }
    if (!inhibit_cleared) {
        return 0;
    }
    u32 status = 0u;
    if (!read32(
            &resources->mmio, 0u,
            OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)) {
        return 0;
    }
    u32 command_status_mask =
        OS_BCM2712_SDHCI_INT_RESPONSE
        | OS_BCM2712_SDHCI_INT_ERROR_MASK;
    u32 stale_status = status & command_status_mask;
    if ((stale_status != 0u
            && !write32(
                &resources->mmio, 0u,
                OS_BCM2712_SDHCI_INTERRUPT_STATUS, stale_status))
        || !read32(
            &resources->mmio, 0u,
            OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)
        || (status & stale_status) != 0u
        || !write32(
            &resources->mmio, 0u,
            OS_BCM2712_SDHCI_ARGUMENT, argument)
        || !resources->mmio.write16(
            resources->mmio.context, 0u,
            OS_BCM2712_SDHCI_COMMAND,
            (u16)(((u16)command_index << 8) | command_flags))) {
        return 0;
    }
    for (u32 poll = 0; poll < poll_limit; ++poll) {
        if (!read32(
                &resources->mmio, 0u,
                OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)) {
            return 0;
        }
        u32 observed = status & command_status_mask;
        if ((observed & OS_BCM2712_SDHCI_INT_ERROR_MASK) != 0u) {
            (void)write32(
                &resources->mmio, 0u,
                OS_BCM2712_SDHCI_INTERRUPT_STATUS, observed);
            return 0;
        }
        if ((observed & OS_BCM2712_SDHCI_INT_RESPONSE) != 0u) {
            u32 response_values[4] = {0u, 0u, 0u, 0u};
            u8 response_type = command_flags & 0x03u;
            if (response_type == OS_BCM2712_SDHCI_CMD_RESP_LONG) {
                for (u32 i = 0; i < 4u; ++i) {
                    if (!read32(
                            &resources->mmio, 0u,
                            OS_BCM2712_SDHCI_RESPONSE0
                                + (3u - i) * 4u,
                            &response_values[i])) {
                        return 0;
                    }
                }
                for (u32 i = 0; i < 4u; ++i) {
                    response_values[i] <<= 8;
                    if (i != 3u) {
                        response_values[i] |= response_values[i + 1u] >> 24;
                    }
                }
            } else if (response_type
                != OS_BCM2712_SDHCI_CMD_RESP_NONE) {
                if (!read32(
                        &resources->mmio, 0u,
                        OS_BCM2712_SDHCI_RESPONSE0,
                        &response_values[0])) {
                    return 0;
                }
            }
            if (!write32(
                    &resources->mmio, 0u,
                    OS_BCM2712_SDHCI_INTERRUPT_STATUS, observed)
                || !read32(
                    &resources->mmio, 0u,
                    OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)
                || (status & observed) != 0u) {
                return 0;
            }
            if (response != (u32 *)0) {
                for (u32 i = 0; i < 4u; ++i) {
                    response[i] = response_values[i];
                }
            }
            return 1;
        }
        if (!delay_us(delay_context, 10u, 10u)) {
            return 0;
        }
    }
    return 0;
}

int os_pi5_bcm2712_sdio_cmd52(
    os_pi5_bcm2712_sdhci_resources *resources,
    u8 function,
    u32 address,
    int write,
    int read_after_write,
    u8 value,
    u32 poll_limit,
    os_pi5_delay_us delay_us,
    void *delay_context,
    u8 *result
)
{
    if (result != (u8 *)0) {
        *result = 0u;
    }
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || function > OS_BCM2712_SDIO_CMD52_MAX_FUNCTION
        || address > OS_BCM2712_SDIO_CMD52_MAX_ADDRESS
        || (write != 0 && write != 1)
        || (read_after_write != 0 && read_after_write != 1)
        || (read_after_write && !write)
        || ((!write || read_after_write) && result == (u8 *)0)) {
        return 0;
    }

    u32 argument = ((u32)function
            << OS_BCM2712_SDIO_CMD52_FUNCTION_SHIFT)
        | (address << OS_BCM2712_SDIO_CMD52_ADDRESS_SHIFT);
    if (write) {
        argument |= OS_BCM2712_SDIO_CMD52_WRITE | value;
    }
    if (read_after_write) {
        argument |= OS_BCM2712_SDIO_CMD52_RAW;
    }

    u32 response[4] = {0u, 0u, 0u, 0u};
    u8 flags = OS_BCM2712_SDHCI_CMD_RESP_SHORT
        | OS_BCM2712_SDHCI_CMD_CRC
        | OS_BCM2712_SDHCI_CMD_INDEX;
    if (!os_pi5_bcm2712_sdhci_send_command(
            resources, OS_BCM2712_SDIO_CMD_IO_RW_DIRECT,
            argument, flags, poll_limit, delay_us,
            delay_context, response)
        || (response[0] & OS_BCM2712_SDIO_R5_STATUS_MASK) != 0u) {
        return 0;
    }
    if (result != (u8 *)0) {
        *result = (u8)response[0];
    }
    return 1;
}

static int bcm2712_sdio_r4_decode(
    u32 response,
    os_pi5_bcm2712_sdio_card_info *card_info
)
{
    if (card_info == (os_pi5_bcm2712_sdio_card_info *)0) {
        return 0;
    }
    card_info->ocr = 0u;
    card_info->function_count = 0u;
    card_info->memory_present = 0u;
    card_info->card_ready = 0u;

    u32 function_count =
        (response & OS_BCM2712_SDIO_R4_FUNCTION_COUNT_MASK)
        >> OS_BCM2712_SDIO_R4_FUNCTION_COUNT_SHIFT;
    u32 ocr = response & OS_BCM2712_SDIO_R4_OCR_MASK;
    if (function_count == 0u
        || (ocr & OS_BCM2712_SDHCI_OCR_VOLTAGE_MASK) == 0u) {
        return 0;
    }

    card_info->ocr = ocr;
    card_info->function_count = (u8)function_count;
    card_info->memory_present =
        (response & OS_BCM2712_SDIO_R4_MEMORY_PRESENT) != 0u;
    card_info->card_ready =
        (response & OS_BCM2712_SDIO_R4_READY) != 0u;
    return 1;
}

int os_pi5_bcm2712_sdio_query_op_cond(
    os_pi5_bcm2712_sdhci_resources *resources,
    u32 poll_limit,
    os_pi5_delay_us delay_us,
    void *delay_context,
    os_pi5_bcm2712_sdio_card_info *card_info
)
{
    if (card_info != (os_pi5_bcm2712_sdio_card_info *)0) {
        card_info->ocr = 0u;
        card_info->function_count = 0u;
        card_info->memory_present = 0u;
        card_info->card_ready = 0u;
    }
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || card_info == (os_pi5_bcm2712_sdio_card_info *)0) {
        return 0;
    }

    u32 response[4] = {0u, 0u, 0u, 0u};
    if (!os_pi5_bcm2712_sdhci_send_command(
            resources, OS_BCM2712_SDIO_CMD_IO_SEND_OP_COND, 0u,
            OS_BCM2712_SDHCI_CMD_RESP_SHORT, poll_limit,
            delay_us, delay_context, response)) {
        return 0;
    }
    return bcm2712_sdio_r4_decode(response[0], card_info);
}

int os_pi5_bcm2712_sdio_negotiate_op_cond(
    os_pi5_bcm2712_sdhci_resources *resources,
    u32 host_ocr,
    u32 poll_limit,
    os_pi5_delay_us delay_us,
    void *delay_context,
    os_pi5_bcm2712_sdio_card_info *card_info
)
{
    if (card_info != (os_pi5_bcm2712_sdio_card_info *)0) {
        card_info->ocr = 0u;
        card_info->function_count = 0u;
        card_info->memory_present = 0u;
        card_info->card_ready = 0u;
    }
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || card_info == (os_pi5_bcm2712_sdio_card_info *)0
        || host_ocr == 0u
        || (host_ocr & ~OS_BCM2712_SDHCI_OCR_VOLTAGE_MASK) != 0u
        || poll_limit == 0u
        || poll_limit > OS_BCM2712_SDHCI_OCR_POLL_LIMIT
        || delay_us == (os_pi5_delay_us)0) {
        return 0;
    }

    os_pi5_bcm2712_sdio_card_info initial_info = {0};
    if (!os_pi5_bcm2712_sdio_query_op_cond(
            resources, OS_BCM2712_SDHCI_COMMAND_POLL_LIMIT,
            delay_us, delay_context, &initial_info)) {
        return 0;
    }
    u32 selected_ocr = initial_info.ocr & host_ocr;
    if (selected_ocr == 0u) {
        return 0;
    }

    for (u32 poll = 0u; poll < poll_limit; ++poll) {
        u32 response[4] = {0u, 0u, 0u, 0u};
        os_pi5_bcm2712_sdio_card_info current_info = {0};
        if (!os_pi5_bcm2712_sdhci_send_command(
                resources, OS_BCM2712_SDIO_CMD_IO_SEND_OP_COND,
                selected_ocr, OS_BCM2712_SDHCI_CMD_RESP_SHORT,
                OS_BCM2712_SDHCI_COMMAND_POLL_LIMIT,
                delay_us, delay_context, response)
            || !bcm2712_sdio_r4_decode(
                response[0], &current_info)
            || current_info.function_count
                != initial_info.function_count
            || current_info.ocr != initial_info.ocr
            || current_info.memory_present
                != initial_info.memory_present) {
            return 0;
        }
        if (current_info.card_ready) {
            *card_info = current_info;
            return 1;
        }
        if (poll + 1u < poll_limit
            && !delay_us(
                delay_context,
                OS_BCM2712_SDIO_OCR_POLL_DELAY_US,
                OS_BCM2712_SDIO_OCR_POLL_DELAY_US)) {
            return 0;
        }
    }
    return 0;
}

static int bcm2712_sdhci_response_bits(
    const u32 response[4],
    u32 start_bit,
    u32 bit_count,
    u32 *value
)
{
    if (response == (const u32 *)0 || value == (u32 *)0
        || bit_count == 0u || bit_count > 32u
        || start_bit > 127u || bit_count > 128u - start_bit) {
        return 0;
    }
    u32 result = 0u;
    for (u32 bit = 0; bit < bit_count; ++bit) {
        u32 position = start_bit + bit;
        u32 word = 3u - position / 32u;
        u32 bit_value = (response[word] >> (position % 32u)) & 1u;
        result |= bit_value << bit;
    }
    *value = result;
    return 1;
}

static int bcm2712_sdhci_send_sd_command(
    os_pi5_bcm2712_sdhci_resources *resources,
    u8 index,
    u32 argument,
    u8 flags,
    os_pi5_delay_us delay_us,
    void *delay_context,
    u32 response[4]
)
{
    return os_pi5_bcm2712_sdhci_send_command(
        resources, index, argument, flags,
        OS_BCM2712_SDHCI_COMMAND_POLL_LIMIT,
        delay_us, delay_context, response);
}

int os_pi5_bcm2712_sdhci_identify_sd_card(
    os_pi5_bcm2712_sdhci_resources *resources,
    os_pi5_bcm2712_sd_gpio_supply *supply,
    u32 ocr_poll_limit,
    os_pi5_delay_us delay_us,
    void *delay_context,
    os_pi5_bcm2712_sd_card *card
)
{
    if (card != (os_pi5_bcm2712_sd_card *)0) {
        card->ocr = 0u;
        card->relative_address = 0u;
        card->block_count = 0u;
        for (usize i = 0; i < 4u; ++i) {
            card->cid[i] = 0u;
            card->csd[i] = 0u;
        }
        card->high_capacity = 0u;
        card->initialized = 0u;
    }
    if (resources == (os_pi5_bcm2712_sdhci_resources *)0
        || !resources->ready || !resources->controller_reset
        || !resources->power_active || !resources->clock_active
        || supply == (os_pi5_bcm2712_sd_gpio_supply *)0
        || !supply->ready || !supply->active || supply->faulted
        || ocr_poll_limit == 0u
        || ocr_poll_limit > OS_BCM2712_SDHCI_OCR_POLL_LIMIT
        || delay_us == (os_pi5_delay_us)0
        || card == (os_pi5_bcm2712_sd_card *)0) {
        return 0;
    }
    int present = 0;
    if (!os_pi5_bcm2712_sd_gpio_card_present(supply, &present)
        || !present) {
        return 0;
    }
    u32 response[4] = {0u, 0u, 0u, 0u};
    u32 csd_structure = 0u;
    u32 csd_size = 0u;
    u8 short_crc_index =
        OS_BCM2712_SDHCI_CMD_RESP_SHORT
        | OS_BCM2712_SDHCI_CMD_CRC
        | OS_BCM2712_SDHCI_CMD_INDEX;
    u8 long_crc = OS_BCM2712_SDHCI_CMD_RESP_LONG
        | OS_BCM2712_SDHCI_CMD_CRC;
    if (!bcm2712_sdhci_send_sd_command(
            resources, 0u, 0u,
            OS_BCM2712_SDHCI_CMD_RESP_NONE,
            delay_us, delay_context, (u32 *)0)
        || !bcm2712_sdhci_send_sd_command(
            resources, 8u, 0x1aau, short_crc_index,
            delay_us, delay_context, response)
        || (response[0] & 0x0fffu) != 0x01aau) {
        return 0;
    }
    int card_ready = 0;
    for (u32 poll = 0; poll < ocr_poll_limit; ++poll) {
        if (!bcm2712_sdhci_send_sd_command(
                resources, 55u, 0u, short_crc_index,
                delay_us, delay_context, response)
            || (response[0] & (1u << 5)) == 0u
            || !bcm2712_sdhci_send_sd_command(
                resources, 41u, OS_BCM2712_SDHCI_OCR_ARGUMENT,
                OS_BCM2712_SDHCI_CMD_RESP_SHORT,
                delay_us, delay_context, response)) {
            return 0;
        }
        card->ocr = response[0];
        if ((card->ocr & OS_BCM2712_SDHCI_OCR_READY) != 0u) {
            card_ready = 1;
            break;
        }
        if (!delay_us(delay_context, 4000u, 4000u)) {
            return 0;
        }
    }
    if (!card_ready
        || (card->ocr & OS_BCM2712_SDHCI_OCR_VOLTAGE_MASK) == 0u
        || (card->ocr & OS_BCM2712_SDHCI_OCR_HIGH_CAPACITY) == 0u
        || !bcm2712_sdhci_send_sd_command(
            resources, 2u, 0u, long_crc,
            delay_us, delay_context, card->cid)
        || !bcm2712_sdhci_send_sd_command(
            resources, 3u, 0u, short_crc_index,
            delay_us, delay_context, response)) {
        return 0;
    }
    card->relative_address = response[0] & 0xffff0000u;
    if (card->relative_address == 0u
        || !bcm2712_sdhci_send_sd_command(
            resources, 9u, card->relative_address, long_crc,
            delay_us, delay_context, card->csd)
        || !bcm2712_sdhci_response_bits(
            card->csd, 126u, 2u, &csd_structure)
        || csd_structure != 1u
        || !bcm2712_sdhci_response_bits(
            card->csd, 48u, 22u, &csd_size)
        || ((u64)csd_size + 1u) * 1024u > 0xffffffffu
        || !bcm2712_sdhci_send_sd_command(
            resources, 7u, card->relative_address,
            OS_BCM2712_SDHCI_CMD_RESP_SHORT_BUSY
                | OS_BCM2712_SDHCI_CMD_CRC
                | OS_BCM2712_SDHCI_CMD_INDEX,
            delay_us, delay_context, response)
        || !os_pi5_bcm2712_sd_gpio_card_present(supply, &present)
        || !present) {
        return 0;
    }
    card->block_count = (csd_size + 1u) * 1024u;
    if (card->block_count == 0u) {
        return 0;
    }
    card->high_capacity = 1u;
    card->initialized = 1u;
    return 1;
}

void os_pi5_bcm2712_sd_storage_init_state(
    os_pi5_bcm2712_sd_storage *storage
)
{
    if (storage == (os_pi5_bcm2712_sd_storage *)0) {
        return;
    }
    storage->device.context = (void *)0;
    storage->device.block_count = 0u;
    storage->device.read_block = (os_storage_read_block)0;
    storage->device.write_block = (os_storage_write_block)0;
    storage->host = (os_pi5_bcm2712_sdhci_resources *)0;
    storage->irq_controller = (os_pi5_gicv2 *)0;
    storage->supply = (os_pi5_bcm2712_sd_gpio_supply *)0;
    storage->card = (const os_pi5_bcm2712_sd_card *)0;
    storage->irq_write_buffer = (const u8 *)0;
    storage->irq_read_buffer = (u8 *)0;
    storage->delay_us = (os_pi5_delay_us)0;
    storage->delay_context = (void *)0;
    storage->poll_limit = 0u;
    storage->irq_word_index = 0u;
    storage->original_interrupt_enable = 0u;
    storage->original_signal_enable = 0u;
    storage->original_block_size = 0u;
    storage->original_block_count = 0u;
    storage->original_transfer_mode = 0u;
    storage->active = 0u;
    storage->faulted = 0u;
    storage->irq_bound = 0u;
    storage->irq_enabled = 0u;
    storage->irq_transfer_state =
        OS_BCM2712_SDHCI_STORAGE_TRANSFER_IDLE;
    storage->irq_transfer_write = 0u;
    storage->irq_data_end_seen = 0u;
    storage->ready = 0u;
}

int os_pi5_bcm2712_sd_storage_attach(
    os_pi5_bcm2712_sd_storage *storage,
    os_pi5_bcm2712_sdhci_resources *host,
    os_pi5_bcm2712_sd_gpio_supply *supply,
    const os_pi5_bcm2712_sd_card *card,
    u32 poll_limit,
    os_pi5_delay_us delay_us,
    void *delay_context
)
{
    if (storage == (os_pi5_bcm2712_sd_storage *)0
        || storage->ready || host == (os_pi5_bcm2712_sdhci_resources *)0
        || !host->ready || !host->controller_reset || !host->power_active
        || !host->clock_active
        || supply == (os_pi5_bcm2712_sd_gpio_supply *)0
        || !supply->ready || !supply->active || supply->faulted
        || card == (const os_pi5_bcm2712_sd_card *)0
        || !card->initialized || !card->high_capacity
        || card->block_count == 0u
        || poll_limit == 0u
        || poll_limit > OS_BCM2712_SDHCI_MAX_POLL_LIMIT
        || delay_us == (os_pi5_delay_us)0) {
        return 0;
    }
    int present = 0;
    if (!os_pi5_bcm2712_sd_gpio_card_present(supply, &present)
        || !present) {
        return 0;
    }
    storage->device.context = storage;
    storage->device.block_count = card->block_count;
    storage->device.read_block = os_pi5_bcm2712_sd_storage_read_block;
    storage->device.write_block = os_pi5_bcm2712_sd_storage_write_block;
    storage->host = host;
    storage->supply = supply;
    storage->card = card;
    storage->delay_us = delay_us;
    storage->delay_context = delay_context;
    storage->poll_limit = poll_limit;
    storage->active = 0u;
    storage->faulted = 0u;
    storage->irq_transfer_state =
        OS_BCM2712_SDHCI_STORAGE_TRANSFER_IDLE;
    storage->ready = 1u;
    return 1;
}

static int bcm2712_sdhci_clear_status(
    os_pi5_bcm2712_sdhci_resources *host,
    u32 status_mask
)
{
    u32 status = 0u;
    if (!read32(
            &host->mmio, 0u,
            OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)) {
        return 0;
    }
    u32 clear = status & status_mask;
    if (clear == 0u) {
        return 1;
    }
    return write32(
            &host->mmio, 0u,
            OS_BCM2712_SDHCI_INTERRUPT_STATUS, clear)
        && read32(
            &host->mmio, 0u,
            OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)
        && (status & clear) == 0u;
}

static int bcm2712_sdhci_wait_status(
    os_pi5_bcm2712_sd_storage *storage,
    u32 expected_status,
    u32 *observed_status
)
{
    if (observed_status != (u32 *)0) {
        *observed_status = 0u;
    }
    if (storage == (os_pi5_bcm2712_sd_storage *)0
        || observed_status == (u32 *)0) {
        return 0;
    }
    for (u32 poll = 0; poll < storage->poll_limit; ++poll) {
        u32 status = 0u;
        if (!read32(
                &storage->host->mmio, 0u,
                OS_BCM2712_SDHCI_INTERRUPT_STATUS, &status)
            || (status & OS_BCM2712_SDHCI_INT_ERROR_MASK) != 0u) {
            return 0;
        }
        if ((status & expected_status) != 0u) {
            *observed_status = status;
            return 1;
        }
        if (!storage->delay_us(
                storage->delay_context, 10u, 10u)) {
            return 0;
        }
    }
    return 0;
}

static int bcm2712_sdhci_reset_data_line(
    os_pi5_bcm2712_sd_storage *storage
)
{
    if (storage == (os_pi5_bcm2712_sd_storage *)0) {
        return 0;
    }
    os_pi5_bcm2712_sdhci_resources *host = storage->host;
    if (host == (os_pi5_bcm2712_sdhci_resources *)0
        || host->mmio.read8 == (os_pi5_mmio_read8)0
        || host->mmio.write8 == (os_pi5_mmio_write8)0) {
        return 0;
    }
    if (!host->mmio.write8(
            host->mmio.context, 0u,
            OS_BCM2712_SDHCI_SOFTWARE_RESET, 0x04u)) {
        return 0;
    }
    for (u32 poll = 0; poll < OS_BCM2712_SDHCI_RESET_POLL_LIMIT; ++poll) {
        u8 reset = 0u;
        if (!host->mmio.read8(
                host->mmio.context, 0u,
                OS_BCM2712_SDHCI_SOFTWARE_RESET, &reset)) {
            return 0;
        }
        if ((reset & 0x04u) == 0u) {
            return 1;
        }
        if (!storage->delay_us(
                storage->delay_context, 10u, 10u)) {
            return 0;
        }
    }
    return 0;
}

