static int rp1_audio_out_dma_buffer_owned(
    const os_page_pool *page_pool,
    const os_pi5_dma_buffer *buffer,
    u32 owner
)
{
    if (page_pool == (const os_page_pool *)0
        || buffer == (const os_pi5_dma_buffer *)0
        || page_pool->base == (u8 *)0
        || !page_pool->has_physical_base
        || page_pool->page_count == 0u
        || page_pool->page_count > OS_MAX_POOL_PAGES
        || owner == 0u || owner == OS_OWNER_RESERVED
        || !buffer->active || buffer->virtual_address == (void *)0
        || buffer->size == 0u) {
        return 0;
    }

    usize pool_size = page_pool->page_count * OS_PAGE_SIZE;
    usize pool_base = (usize)page_pool->base;
    usize address = (usize)buffer->virtual_address;
    if (address < pool_base || (address & (OS_PAGE_SIZE - 1u)) != 0u) {
        return 0;
    }
    usize offset = address - pool_base;
    if (offset > pool_size || buffer->size > pool_size - offset
        || page_pool->physical_base > ~(u64)0 - (u64)offset) {
        return 0;
    }
    u64 expected_system_address =
        page_pool->physical_base + (u64)offset;
    if (buffer->system_address != expected_system_address
        || buffer->size > ~(u64)0 - expected_system_address
        || buffer->size > ~(u64)0 - buffer->dma_address) {
        return 0;
    }

    usize first_page = offset / OS_PAGE_SIZE;
    usize page_count = (buffer->size - 1u) / OS_PAGE_SIZE + 1u;
    if (first_page >= page_pool->page_count
        || page_count > page_pool->page_count - first_page) {
        return 0;
    }
    for (usize page = 0u; page < page_count; ++page) {
        if (__atomic_load_n(&page_pool->owners[first_page + page], __ATOMIC_ACQUIRE) != owner) {
            return 0;
        }
    }
    return 1;
}

