    publication->irq = (os_pi5_rp1_gem_irq *)0;
    publication->saved_tx_base = 0u;
    publication->saved_rx_base = 0u;
    publication->saved_tx_high = 0u;
    publication->saved_rx_high = 0u;
    publication->restore_mask = 0u;
    publication->extended_addresses = 0u;
    publication->locked = 0u;
    publication->ready = 0u;
