int os_pi5_bcm2712_pcie_map_bar(
    os_pi5_bcm2712_pcie_host *host,
    const os_device_tree_node *host_node,
    const os_pci_function *function,
    u8 bar_index,
    const os_pi5_mmio_mapper *mapper,
    os_pi5_pcie_bar_mapping *mapping
)
{
    if (mapping == (os_pi5_pcie_bar_mapping *)0
        || mapping->active
        || mapper == (const os_pi5_mmio_mapper *)0
        || mapper->map_region == (os_pi5_mmio_map_region)0
        || mapper->unmap_region == (os_pi5_mmio_unmap_region)0) {
        return 0;
    }
    os_pi5_pcie_bar_mapping_init_state(mapping);

    os_pci_bar bar;
    u64 physical_address = 0u;
    if (!os_pi5_bcm2712_pcie_probe_bar(
            host, function, bar_index, &bar)
        || !os_pi5_bcm2712_pcie_translate_bar(
            host_node, &bar, &physical_address)
        || bar.size > 0xffffffffu || bar.size < sizeof(u32)
        || (bar.size & (sizeof(u32) - 1u)) != 0u
        || (physical_address & (sizeof(u32) - 1u)) != 0u) {
        return 0;
    }

    volatile u32 *mapped_base = (volatile u32 *)0;
    if (!mapper->map_region(
            mapper->context, physical_address, (u32)bar.size,
            &mapped_base)
        || mapped_base == (volatile u32 *)0) {
        if (mapped_base != (volatile u32 *)0) {
            mapper->unmap_region(
                mapper->context, mapped_base, (u32)bar.size);
        }
        return 0;
    }

    mapping->mapper = *mapper;
    mapping->bar = bar;
    mapping->physical_address = physical_address;
    mapping->mapped_size = (u32)bar.size;
    mapping->direct.region_bases[0] = mapped_base;
    mapping->direct.region_sizes[0] = (u32)bar.size;
    mapping->mmio.context = &mapping->direct;
    mapping->mmio.region_sizes[0] = (u32)bar.size;
    mapping->mmio.read32 = direct_read32;
    mapping->mmio.write32 = direct_write32;
    mapping->mmio.read8 = direct_read8;
    mapping->mmio.write8 = direct_write8;
    mapping->mmio.read16 = direct_read16;
    mapping->mmio.write16 = direct_write16;
    mapping->active = 1u;
    return 1;
}

