    os_pi5_pcie_bar_mapping_init_state(&resource->mapping);
    os_pi5_pcie_allocation_init_state(&resource->allocation);
    resource->function.bus = 0u;
    resource->function.device = 0u;
    resource->function.function = 0u;
    resource->function.header_type = 0u;
    resource->function.vendor_id = 0u;
    resource->function.device_id = 0u;
    resource->original_command = 0u;
    resource->original_bar_low = 0u;
    resource->original_bar_high = 0u;
    resource->bar_index = 0u;
    resource->is_64_bit = 0u;
    resource->owns_assignment = 0u;
