int os_pi5_bcm2712_pcie_bar_acquire(
    os_pi5_bcm2712_pcie_host *host,
    const os_device_tree_node *host_node,
    os_pi5_pcie_resource_allocator *allocator,
    const os_pci_function *function,
    u8 bar_index,
    const os_pi5_mmio_mapper *mapper,
    os_pi5_pcie_bar_resource *resource
)
{
    if (resource == (os_pi5_pcie_bar_resource *)0 || resource->active
        || host == (os_pi5_bcm2712_pcie_host *)0
        || allocator == (os_pi5_pcie_resource_allocator *)0
        || !allocator->ready
        || mapper == (const os_pi5_mmio_mapper *)0
        || function == (const os_pci_function *)0) {
        return 0;
    }
    os_pi5_pcie_bar_resource_init_state(resource);

    os_pci_bar bar;
    u32 command_status = 0u;
    u16 bar_offset = (u16)(OS_PI5_PCI_CONFIG_BAR0 + 4u * bar_index);
    if (!os_pi5_bcm2712_pcie_probe_bar(
            host, function, bar_index, &bar)
        || !bar.implemented || bar.is_io
        || !os_pi5_bcm2712_pcie_config_read32(
            host, function->bus, function->device, function->function,
            OS_PI5_PCI_CONFIG_COMMAND, &command_status)
        || !os_pi5_bcm2712_pcie_config_read32(
            host, function->bus, function->device, function->function,
            bar_offset, &resource->original_bar_low)) {
        return 0;
    }
    if (bar.is_64_bit
        && !os_pi5_bcm2712_pcie_config_read32(
            host, function->bus, function->device, function->function,
            (u16)(bar_offset + 4u), &resource->original_bar_high)) {
        os_pi5_pcie_bar_resource_init_state(resource);
        return 0;
    }
    resource->original_command = command_status & 0xffffu;
    resource->function = *function;
    resource->bar_index = bar_index;
    resource->is_64_bit = bar.is_64_bit;

    int reserved = bar.base == 0u
        ? os_pi5_pcie_resource_allocate(
            allocator, &bar, &resource->allocation)
        : os_pi5_pcie_resource_reserve(
            allocator, host_node, &bar, &resource->allocation);
    if (!reserved) {
        os_pi5_pcie_bar_resource_init_state(resource);
        return 0;
    }
    resource->active = 1u;
    resource->owns_assignment = (u8)(bar.base == 0u);

    if (resource->owns_assignment) {
        u32 disabled_command = resource->original_command & ~7u;
        if (!os_pi5_bcm2712_pcie_config_write32(
                host, function->bus, function->device, function->function,
                OS_PI5_PCI_CONFIG_COMMAND, disabled_command)) {
            (void)os_pi5_pcie_bar_resource_cleanup(
                host, allocator, resource);
            return 0;
        }
        u32 low_flags = resource->original_bar_low & 0x0fu;
        u32 assigned_low =
            ((u32)resource->allocation.pci_address & 0xfffffff0u)
            | low_flags;
        int programmed = 1;
        if (resource->is_64_bit) {
            programmed = os_pi5_bcm2712_pcie_config_write32(
                host, function->bus, function->device, function->function,
                (u16)(bar_offset + 4u),
                (u32)(resource->allocation.pci_address >> 32));
        }
        if (programmed) {
            programmed = os_pi5_bcm2712_pcie_config_write32(
                host, function->bus, function->device,
                function->function, bar_offset, assigned_low);
        }
        u32 observed_low = 0u;
        u32 observed_high = 0u;
        if (programmed) {
            programmed = os_pi5_bcm2712_pcie_config_read32(
                host, function->bus, function->device, function->function,
                bar_offset, &observed_low)
                && observed_low == assigned_low;
        }
        if (programmed && resource->is_64_bit) {
            programmed = os_pi5_bcm2712_pcie_config_read32(
                host, function->bus, function->device, function->function,
                (u16)(bar_offset + 4u), &observed_high)
                && observed_high
                    == (u32)(resource->allocation.pci_address >> 32);
        }
        if (!programmed) {
            (void)os_pi5_pcie_bar_resource_cleanup(
                host, allocator, resource);
            return 0;
        }
        if (!os_pi5_bcm2712_pcie_config_write32(
                host, function->bus, function->device, function->function,
                OS_PI5_PCI_CONFIG_COMMAND, resource->original_command)) {
            return 0;
        }
    }

    if (!os_pi5_bcm2712_pcie_map_bar(
            host, host_node, function, bar_index, mapper,
            &resource->mapping)) {
        (void)os_pi5_pcie_bar_resource_cleanup(
            host, allocator, resource);
        return 0;
    }
    return 1;
}

int os_pi5_pcie_bar_resource_cleanup(
    os_pi5_bcm2712_pcie_host *host,
    os_pi5_pcie_resource_allocator *allocator,
    os_pi5_pcie_bar_resource *resource
)
{
    if (host == (os_pi5_bcm2712_pcie_host *)0
        || allocator == (os_pi5_pcie_resource_allocator *)0
        || resource == (os_pi5_pcie_bar_resource *)0
        || !resource->active) {
        return 0;
    }
    if (resource->mapping.active
        && !os_pi5_pcie_bar_mapping_cleanup(&resource->mapping)) {
        return 0;
    }
    if (resource->owns_assignment) {
        u16 bar_offset = (u16)(
            OS_PI5_PCI_CONFIG_BAR0 + 4u * resource->bar_index);
        u32 disabled_command = resource->original_command & ~7u;
        if (!os_pi5_bcm2712_pcie_config_write32(
                host, resource->function.bus, resource->function.device,
                resource->function.function,
                OS_PI5_PCI_CONFIG_COMMAND, disabled_command)) {
            return 0;
        }
        if (resource->is_64_bit
            && !os_pi5_bcm2712_pcie_config_write32(
                host, resource->function.bus, resource->function.device,
                resource->function.function, (u16)(bar_offset + 4u),
                resource->original_bar_high)) {
            return 0;
        }
        if (!os_pi5_bcm2712_pcie_config_write32(
                host, resource->function.bus, resource->function.device,
                resource->function.function, bar_offset,
                resource->original_bar_low)
            || !os_pi5_bcm2712_pcie_config_write32(
                host, resource->function.bus, resource->function.device,
                resource->function.function, OS_PI5_PCI_CONFIG_COMMAND,
                resource->original_command)) {
            return 0;
        }
    }
    if (!os_pi5_pcie_resource_release(allocator, &resource->allocation)) {
        return 0;
    }
    os_pi5_pcie_bar_resource_init_state(resource);
    return 1;
}

int os_pi5_pcie_bar_mapping_cleanup(
    os_pi5_pcie_bar_mapping *mapping
)
{
    if (mapping == (os_pi5_pcie_bar_mapping *)0 || !mapping->active
        || mapping->mapper.unmap_region
            == (os_pi5_mmio_unmap_region)0
        || mapping->direct.region_bases[0] == (volatile u32 *)0
        || mapping->mapped_size == 0u) {
        return 0;
    }
    mapping->mapper.unmap_region(
        mapping->mapper.context, mapping->direct.region_bases[0],
        mapping->mapped_size);
    os_pi5_pcie_bar_mapping_init_state(mapping);
    return 1;
}

int os_pi5_bcm2712_pcie_scan(
    os_pi5_bcm2712_pcie_host *host,
    os_pci_function *functions,
    usize capacity,
    usize *function_count
)
{
    if (function_count != (usize *)0) {
        *function_count = 0;
    }
    if (host == (os_pi5_bcm2712_pcie_host *)0 || !host->ready
        || functions == (os_pci_function *)0 || capacity == 0
        || function_count == (usize *)0) {
        return 0;
    }
    usize count = 0;
    for (u32 bus = host->first_bus; bus <= host->last_bus; ++bus) {
        u32 device_limit = bus == host->first_bus ? 1u : 32u;
        for (u32 device = 0; device < device_limit; ++device) {
            u32 function_limit = 1u;
            for (u32 function = 0; function < function_limit; ++function) {
                u32 identity = 0xffffffffu;
                u32 header = 0;
                if (!os_pi5_bcm2712_pcie_config_read32(
                        host, (u8)bus, (u8)device, (u8)function, 0u,
                        &identity)) {
                    if (bus != host->first_bus && !host->link_up) {
                        *function_count = count;
                        return 1;
                    }
                    *function_count = count;
                    return 0;
                }
                if ((u16)identity == 0xffffu) {
                    continue;
                }
                if (!os_pi5_bcm2712_pcie_config_read32(
                        host, (u8)bus, (u8)device, (u8)function, 0x0cu,
                        &header)) {
                    *function_count = count;
                    return 0;
                }
                u8 header_type = (u8)(header >> 16);
                if (function == 0u && (header_type & 0x80u) != 0) {
                    function_limit = 8u;
                }
                if (count == capacity) {
                    *function_count = count;
                    return 0;
                }
                functions[count].bus = (u8)bus;
                functions[count].device = (u8)device;
                functions[count].function = (u8)function;
                functions[count].header_type = header_type & 0x7fu;
                functions[count].vendor_id = (u16)identity;
                functions[count].device_id = (u16)(identity >> 16);
                ++count;
            }
        }
    }
    *function_count = count;
    return 1;
}

int os_pi5_bcm2712_pcie_host_cleanup(
    os_pi5_bcm2712_pcie_host *host
)
{
    if (host == (os_pi5_bcm2712_pcie_host *)0 || !host->ready) {
        return 0;
    }
    if (host->owns_mapping) {
        os_pi5_mmio_unmap(&host->mapping);
    }
    os_pi5_bcm2712_pcie_host_init_state(host);
    return 1;
}

int os_pi5_pcie_scan(
    os_pi5_mmio *configuration_space,
    u8 first_bus,
    u8 last_bus,
    os_pci_function *functions,
    usize capacity,
    usize *function_count
)
{
    if (function_count != (usize *)0) {
        *function_count = 0;
    }
    if (configuration_space == (os_pi5_mmio *)0
        || configuration_space->read32 == (os_pi5_mmio_read32)0
        || functions == (os_pci_function *)0 || capacity == 0
        || function_count == (usize *)0 || first_bus > last_bus) {
        return 0;
    }
    usize count = 0;
    for (u32 bus = first_bus; bus <= last_bus; ++bus) {
        for (u32 device = 0; device < 32u; ++device) {
            u32 function_limit = 1u;
            for (u32 function = 0; function < function_limit; ++function) {
                u32 offset = (bus << 20) | (device << 15)
                    | (function << 12);
                u32 identity = 0xffffffffu;
                if (!read32(configuration_space, 0u, offset, &identity)) {
                    *function_count = count;
                    return 0;
                }
                u16 vendor_id = (u16)identity;
                if (vendor_id == 0xffffu) {
                    continue;
                }
                u32 header = 0;
                if (!read32(
                        configuration_space, 0u, offset + 0x0cu, &header)) {
                    *function_count = count;
                    return 0;
                }
                u8 header_type = (u8)(header >> 16);
                if (function == 0 && (header_type & 0x80u) != 0) {
                    function_limit = 8u;
                }
                if (count >= capacity) {
                    *function_count = count;
                    return 0;
                }
                functions[count].bus = (u8)bus;
                functions[count].device = (u8)device;
                functions[count].function = (u8)function;
                functions[count].header_type = header_type & 0x7fu;
                functions[count].vendor_id = vendor_id;
                functions[count].device_id = (u16)(identity >> 16);
                ++count;
            }
        }
    }
    *function_count = count;
    return 1;
}

int os_pi5_pcie_find_rp1(
    const os_pci_function *functions,
    usize function_count,
    usize *rp1_index
)
{
    if (rp1_index != (usize *)0) {
        *rp1_index = 0;
    }
    if (functions == (const os_pci_function *)0
        || function_count == 0 || rp1_index == (usize *)0) {
        return 0;
    }
    usize found = 0;
    for (usize i = 0; i < function_count; ++i) {
        if (functions[i].vendor_id == OS_PI5_PCI_VENDOR_RPI
            && functions[i].device_id == OS_PI5_PCI_DEVICE_RP1_C0) {
            if (found != 0) {
                return 0;
            }
            *rp1_index = i;
            ++found;
        }
    }
    return found == 1u;
}

int os_pi5_bcm2712_pcie_find_msix(
    os_pi5_bcm2712_pcie_host *host,
    const os_pci_function *function,
    os_pci_msix_capability *capability
)
{
    if (capability != (os_pci_msix_capability *)0) {
        capability->table_offset = 0u;
        capability->pba_offset = 0u;
        capability->capability_offset = 0u;
        capability->table_size = 0u;
        capability->table_bar_index = 0u;
        capability->pba_bar_index = 0u;
        capability->control = 0u;
    }
    if (host == (os_pi5_bcm2712_pcie_host *)0 || !host->ready
        || function == (const os_pci_function *)0
        || function->header_type != 0u
        || capability == (os_pci_msix_capability *)0) {
        return 0;
    }

    u32 command_status = 0u;
    u32 capability_pointer = 0u;
    if (!os_pi5_bcm2712_pcie_config_read32(
            host, function->bus, function->device, function->function,
            OS_PI5_PCI_CONFIG_COMMAND, &command_status)
        || (((command_status >> 16) & (1u << 4)) == 0u)
        || !os_pi5_bcm2712_pcie_config_read32(
            host, function->bus, function->device, function->function,
            OS_PI5_PCI_CONFIG_CAPABILITIES, &capability_pointer)) {
        return 0;
    }

    u32 pointer = capability_pointer & 0xffu;
    u64 visited = 0u;
    u32 found = 0u;
    os_pci_msix_capability found_capability;
    for (u32 count = 0u; count < 48u && pointer != 0u; ++count) {
        if (pointer < 0x40u || pointer > 0xfcu || (pointer & 3u) != 0u) {
            return 0;
        }
        u32 slot = (pointer - 0x40u) >> 2;
        u64 slot_mask = (u64)1u << slot;
        if ((visited & slot_mask) != 0u) {
            return 0;
        }
        visited |= slot_mask;

        u32 header = 0u;
        if (!os_pi5_bcm2712_pcie_config_read32(
                host, function->bus, function->device, function->function,
                (u16)pointer, &header)) {
            return 0;
        }
        if ((header & 0xffu) == OS_PI5_PCI_CAPABILITY_MSIX) {
            if (found != 0u || pointer > 0xf4u) {
                return 0;
            }
            u32 table = 0u;
            u32 pba = 0u;
            u16 control = (u16)(header >> 16);
            if (!os_pi5_bcm2712_pcie_config_read32(
                    host, function->bus, function->device,
                    function->function, (u16)(pointer + 4u), &table)
                || !os_pi5_bcm2712_pcie_config_read32(
                    host, function->bus, function->device,
                    function->function, (u16)(pointer + 8u), &pba)
                || (table & 7u) >= 6u || (pba & 7u) >= 6u) {
                return 0;
            }
            found_capability.capability_offset = (u16)pointer;
            found_capability.control = control;
            found_capability.table_size =
                (u16)((control & 0x07ffu) + 1u);
            found_capability.table_bar_index = (u8)(table & 7u);
            found_capability.table_offset = table & 0xfffffff8u;
            found_capability.pba_bar_index = (u8)(pba & 7u);
            found_capability.pba_offset = pba & 0xfffffff8u;
            found = 1u;
        }
        pointer = (header >> 8) & 0xffu;
    }
    if (found != 1u || pointer != 0u) {
        return 0;
    }
    *capability = found_capability;
    return 1;
}

void os_pi5_rp1_pci_init_state(os_pi5_rp1_pci *rp1)
{
    if (rp1 == (os_pi5_rp1_pci *)0) {
        return;
    }
    rp1->msix.table_offset = 0u;
    rp1->msix.pba_offset = 0u;
    rp1->msix.capability_offset = 0u;
    rp1->msix.table_size = 0u;
    rp1->msix.table_bar_index = 0u;
    rp1->msix.pba_bar_index = 0u;
    rp1->msix.control = 0u;
    for (usize i = 0; i < OS_PI5_PCI_MAX_BARS; ++i) {
        os_pi5_pcie_bar_resource_init_state(&rp1->bars[i]);
    }
    for (usize i = 0; i < OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT; ++i) {
        os_pi5_mip_vector_init_state(&rp1->vectors[i].vector);
        rp1->vectors[i].rp1 = rp1;
        rp1->vectors[i].handler = (os_pi5_interrupt_handler)0;
        rp1->vectors[i].handler_context = (void *)0;
        for (usize word = 0;
            word < OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32);
            ++word) {
            rp1->vectors[i].original_entry[word] = 0u;
        }
        rp1->vectors[i].active = 0u;
        rp1->vectors[i].level_triggered = 0u;
        rp1->vectors[i].entry_saved = 0u;
        rp1->vectors[i].source_enabled = 0u;
    }
    rp1->mip = (os_pi5_bcm2712_mip *)0;
    rp1->host = (os_pi5_bcm2712_pcie_host *)0;
    rp1->host_node = (const os_device_tree_node *)0;
    rp1->function.bus = 0u;
    rp1->function.device = 0u;
    rp1->function.function = 0u;
    rp1->function.header_type = 0u;
    rp1->function.vendor_id = 0u;
    rp1->function.device_id = 0u;
    rp1->original_msix_control = 0u;
    rp1->active_vector_count = 0u;
    rp1->ready = 0u;
    rp1->msix_control_saved = 0u;
    rp1->dispatch_error = 0u;
    rp1->initialization_failed = 0u;
}

int os_pi5_rp1_pci_attach(
    os_pi5_rp1_pci *rp1,
    os_pi5_bcm2712_pcie_host *host,
    const os_device_tree_node *host_node,
    os_pi5_pcie_resource_allocator *allocator,
    const os_pci_function *functions,
    usize function_count,
    const os_pi5_mmio_mapper *mapper
)
{
    if (rp1 == (os_pi5_rp1_pci *)0 || rp1->ready
        || rp1->initialization_failed || rp1->msix_control_saved
        || host == (os_pi5_bcm2712_pcie_host *)0
        || host_node == (const os_device_tree_node *)0
        || allocator == (os_pi5_pcie_resource_allocator *)0
        || functions == (const os_pci_function *)0
        || mapper == (const os_pi5_mmio_mapper *)0) {
        return 0;
    }
    os_pi5_rp1_pci_init_state(rp1);

    usize rp1_index = 0u;
    os_pci_msix_capability msix;
    os_pci_bar bar;
    if (!os_pi5_pcie_find_rp1(
            functions, function_count, &rp1_index)
        || !os_pi5_bcm2712_pcie_find_msix(
            host, &functions[rp1_index], &msix)
        || msix.table_size < OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT
        || (msix.table_offset & 7u) != 0u
        || (msix.pba_offset & 7u) != 0u
        || !os_pi5_bcm2712_pcie_probe_bar(
            host, &functions[rp1_index], OS_PI5_RP1_PCI_BAR_INDEX, &bar)
        || !bar.implemented || bar.is_io
        || bar.size < OS_PI5_RP1_PCI_MSIX_REGISTER_END) {
        return 0;
    }
    rp1->msix = msix;
    rp1->function = functions[rp1_index];
    rp1->host = host;
    rp1->host_node = host_node;

    u8 required_bars[OS_PI5_PCI_MAX_BARS] = {0};
    required_bars[OS_PI5_RP1_PCI_BAR_INDEX] = 1u;
    required_bars[msix.table_bar_index] = 1u;
    required_bars[msix.pba_bar_index] = 1u;
    for (u32 i = 0; i < OS_PI5_PCI_MAX_BARS; ++i) {
        if (!required_bars[i]) {
            continue;
        }
        if (!os_pi5_bcm2712_pcie_bar_acquire(
                host, host_node, allocator, &rp1->function, (u8)i,
                mapper, &rp1->bars[i])) {
            goto attach_failure;
        }
    }
    if (!rp1->bars[OS_PI5_RP1_PCI_BAR_INDEX].active
        || rp1->bars[OS_PI5_RP1_PCI_BAR_INDEX].mapping.mapped_size
            < OS_PI5_RP1_PCI_MSIX_REGISTER_END
        || (u64)msix.table_offset
            + (u64)msix.table_size * OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE
            > rp1->bars[msix.table_bar_index].mapping.mapped_size
        || (u64)msix.pba_offset
            + (((u64)msix.table_size + 31u) / 32u) * sizeof(u32)
            > rp1->bars[msix.pba_bar_index].mapping.mapped_size) {
        goto attach_failure;
    }
    u32 control_word = 0u;
    if (!os_pi5_bcm2712_pcie_config_read32(
            host, rp1->function.bus, rp1->function.device,
            rp1->function.function, msix.capability_offset, &control_word)) {
        goto attach_failure;
    }
    rp1->original_msix_control = (u16)(control_word >> 16);
    rp1->msix_control_saved = 1u;
    u16 masked_control = (u16)(
        (rp1->original_msix_control
            & (u16)~OS_PI5_PCI_MSIX_CONTROL_ENABLE)
        | OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK);
    if (!os_pi5_bcm2712_pcie_config_write32(
            host, rp1->function.bus, rp1->function.device,
            rp1->function.function, msix.capability_offset,
            (control_word & 0x0000ffffu) | ((u32)masked_control << 16))) {
        goto attach_failure;
    }
    u32 observed_control_word = 0u;
    if (!os_pi5_bcm2712_pcie_config_read32(
            host, rp1->function.bus, rp1->function.device,
            rp1->function.function, msix.capability_offset,
            &observed_control_word)
        || (((u16)(observed_control_word >> 16)
                ^ masked_control)
            & (OS_PI5_PCI_MSIX_CONTROL_ENABLE
                | OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK)) != 0u) {
        goto attach_failure;
    }
    int skip_bar = 0;
    for (u32 i = 0; i < OS_PI5_PCI_MAX_BARS; ++i) {
        if (skip_bar) {
            skip_bar = 0;
            continue;
        }
        if (rp1->bars[i].active) {
            if (rp1->bars[i].mapping.bar.is_64_bit) {
                skip_bar = 1;
            }
            continue;
        }
        if (!os_pi5_bcm2712_pcie_probe_bar(
                host, &rp1->function, (u8)i, &bar)) {
            continue;
        }
        if (bar.is_64_bit) {
            skip_bar = 1;
        }
        u64 physical_address = 0u;
        if (!bar.implemented || bar.is_io || bar.base == 0u
            || bar.size < sizeof(u32) || bar.size > 0xffffffffu
            || !os_pi5_bcm2712_pcie_translate_bar(
                host_node, &bar, &physical_address)) {
            continue;
        }
        if (!os_pi5_bcm2712_pcie_bar_acquire(
                host, host_node, allocator, &rp1->function, (u8)i,
                mapper, &rp1->bars[i])
            && rp1->bars[i].active) {
            goto attach_failure;
        }
    }
    rp1->ready = 1u;
    return 1;

attach_failure:
    if (rp1->msix_control_saved) {
        u32 current_control_word = 0u;
        if (!os_pi5_bcm2712_pcie_config_read32(
                host, rp1->function.bus, rp1->function.device,
                rp1->function.function, rp1->msix.capability_offset,
                &current_control_word)
            || !os_pi5_bcm2712_pcie_config_write32(
                host, rp1->function.bus, rp1->function.device,
                rp1->function.function, rp1->msix.capability_offset,
                (current_control_word & 0x0000ffffu)
                    | ((u32)rp1->original_msix_control << 16))
            || !os_pi5_bcm2712_pcie_config_read32(
                host, rp1->function.bus, rp1->function.device,
                rp1->function.function, rp1->msix.capability_offset,
                &current_control_word)
            || (u16)(current_control_word >> 16)
                != rp1->original_msix_control) {
            rp1->initialization_failed = 1u;
            return 0;
        }
        rp1->msix_control_saved = 0u;
    }
    for (u32 i = OS_PI5_PCI_MAX_BARS; i != 0u; --i) {
        os_pi5_pcie_bar_resource *resource = &rp1->bars[i - 1u];
        if (resource->active) {
            if (!os_pi5_pcie_bar_resource_cleanup(
                    host, allocator, resource)) {
                rp1->initialization_failed = 1u;
                return 0;
            }
        }
    }
    os_pi5_rp1_pci_init_state(rp1);
    return 0;
}

static int rp1_msix_table_region(
    os_pi5_rp1_pci *rp1,
    u32 vector,
    os_pi5_pcie_bar_mapping **mapping,
    u32 *entry_offset
)
{
    if (rp1 == (os_pi5_rp1_pci *)0
        || vector >= OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT
        || mapping == (os_pi5_pcie_bar_mapping **)0
        || entry_offset == (u32 *)0) {
        return 0;
    }
    u32 bir = rp1->msix.table_bar_index;
    if (bir >= OS_PI5_PCI_MAX_BARS || !rp1->bars[bir].active
        || !rp1->bars[bir].mapping.active) {
        return 0;
    }
    u64 offset = (u64)rp1->msix.table_offset
        + (u64)vector * OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE;
    u64 end = offset + OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE;
    if ((offset & 7u) != 0u || end > rp1->bars[bir].mapping.mapped_size
        || end > rp1->bars[bir].mapping.bar.size
        || end > 0xffffffffu) {
        return 0;
    }
    *mapping = &rp1->bars[bir].mapping;
    *entry_offset = (u32)offset;
    return 1;
}

static int rp1_msix_read_entry(
    os_pi5_rp1_pci *rp1,
    u32 vector,
    u32 entry[OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32)]
)
{
    os_pi5_pcie_bar_mapping *mapping = (os_pi5_pcie_bar_mapping *)0;
    u32 offset = 0u;
    if (entry == (u32 *)0
        || !rp1_msix_table_region(rp1, vector, &mapping, &offset)) {
        return 0;
    }
    for (u32 i = 0; i < OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32);
        ++i) {
        if (!read32(&mapping->mmio, 0u, offset + i * sizeof(u32),
                &entry[i])) {
            return 0;
        }
    }
    return 1;
}

static int rp1_msix_write_entry(
    os_pi5_rp1_pci *rp1,
    u32 vector,
    const u32 entry[OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32)]
)
{
    os_pi5_pcie_bar_mapping *mapping = (os_pi5_pcie_bar_mapping *)0;
    u32 offset = 0u;
    if (entry == (const u32 *)0
        || !rp1_msix_table_region(rp1, vector, &mapping, &offset)) {
        return 0;
    }
    for (u32 i = 0; i < OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32);
        ++i) {
        u32 observed = 0u;
        if (!write32(&mapping->mmio, 0u, offset + i * sizeof(u32),
                entry[i])
            || !read32(
                &mapping->mmio, 0u, offset + i * sizeof(u32),
                &observed)
            || observed != entry[i]) {
            return 0;
        }
    }
    return 1;
}

static int rp1_msix_mask_entry(os_pi5_rp1_pci *rp1, u32 vector, int masked)
{
    u32 entry[OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32)];
    os_pi5_pcie_bar_mapping *mapping = (os_pi5_pcie_bar_mapping *)0;
    u32 offset = 0u;
    if (!rp1_msix_read_entry(rp1, vector, entry)) {
        return 0;
    }
    if (!rp1_msix_table_region(rp1, vector, &mapping, &offset)) {
        return 0;
    }
    if (masked) {
        entry[3] |= OS_PI5_PCI_MSIX_TABLE_VECTOR_MASK;
    } else {
        entry[3] &= ~OS_PI5_PCI_MSIX_TABLE_VECTOR_MASK;
    }
    return write32(&mapping->mmio, 0u,
        offset + 3u * sizeof(u32), entry[3]);
}

static int rp1_msix_update_function_control(
    os_pi5_rp1_pci *rp1,
    u16 set_bits,
    u16 clear_bits
)
{
    u32 control_word = 0u;
    if (rp1 == (os_pi5_rp1_pci *)0 || !rp1->msix_control_saved
        || !os_pi5_bcm2712_pcie_config_read32(
            rp1->host, rp1->function.bus, rp1->function.device,
            rp1->function.function, rp1->msix.capability_offset,
            &control_word)) {
        return 0;
    }
    u16 control = (u16)(control_word >> 16);
    control = (u16)((control | set_bits) & (u16)~clear_bits);
    if (!os_pi5_bcm2712_pcie_config_write32(
        rp1->host, rp1->function.bus, rp1->function.device,
        rp1->function.function, rp1->msix.capability_offset,
        (control_word & 0x0000ffffu) | ((u32)control << 16))
        || !os_pi5_bcm2712_pcie_config_read32(
            rp1->host, rp1->function.bus, rp1->function.device,
            rp1->function.function, rp1->msix.capability_offset,
            &control_word)) {
        return 0;
    }
    return (((u16)(control_word >> 16) ^ control)
        & (OS_PI5_PCI_MSIX_CONTROL_ENABLE
            | OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK)) == 0u;
}

static int rp1_msix_restore_function_state(os_pi5_rp1_pci *rp1)
{
    if (rp1->active_vector_count == 0u) {
        return rp1_msix_update_function_control(
            rp1, OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK,
            OS_PI5_PCI_MSIX_CONTROL_ENABLE);
    }
    return rp1_msix_update_function_control(
        rp1, OS_PI5_PCI_MSIX_CONTROL_ENABLE,
        OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK);
}

static int rp1_msix_cfg_update(
    os_pi5_rp1_pci *rp1,
    u32 vector,
    u32 flags,
    u32 register_offset
)
{
    if (rp1 == (os_pi5_rp1_pci *)0 || !rp1->ready
        || !rp1->bars[OS_PI5_RP1_PCI_BAR_INDEX].active
        || !rp1->bars[OS_PI5_RP1_PCI_BAR_INDEX].mapping.active
        || vector >= OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT
        || flags == 0u
        || (flags & ~OS_PI5_RP1_PCI_MSIX_CFG_VALID_MASK) != 0u) {
        return 0;
    }
    u32 offset = OS_PI5_RP1_PCI_APBS_BASE + register_offset
        + OS_PI5_RP1_PCI_MSIX_CFG_OFFSET + 4u * vector;
    return write32(
        &rp1->bars[OS_PI5_RP1_PCI_BAR_INDEX].mapping.mmio,
        0u, offset, flags);
}

int os_pi5_rp1_pci_msix_cfg_set(
    os_pi5_rp1_pci *rp1,
    u32 vector,
    u32 flags
)
{
    return rp1_msix_cfg_update(
        rp1, vector, flags, OS_PI5_RP1_PCI_APBS_REG_SET);
}

int os_pi5_rp1_pci_msix_cfg_clear(
    os_pi5_rp1_pci *rp1,
    u32 vector,
    u32 flags
)
{
    return rp1_msix_cfg_update(
        rp1, vector, flags, OS_PI5_RP1_PCI_APBS_REG_CLR);
}

static void rp1_msix_interrupt(void *context, u32 message_data)
{
    os_pi5_rp1_msix_vector *state =
        (os_pi5_rp1_msix_vector *)context;
    if (state == (os_pi5_rp1_msix_vector *)0 || !state->active
        || state->handler == (os_pi5_interrupt_handler)0) {
        return;
    }
    os_pi5_rp1_pci *rp1 = state->rp1;
    if (rp1 == (os_pi5_rp1_pci *)0) {
        return;
    }
    state->handler(state->handler_context,
        (u32)(state - rp1->vectors));
    (void)message_data;
    if (state->level_triggered
        && !os_pi5_rp1_pci_msix_cfg_set(
            rp1, (u32)(state - rp1->vectors),
            OS_PI5_RP1_PCI_MSIX_CFG_IACK)) {
        rp1->dispatch_error = 1u;
    }
}

int os_pi5_rp1_pci_msix_bind(
    os_pi5_rp1_pci *rp1,
    os_pi5_bcm2712_mip *mip,
    u32 vector,
    os_pi5_interrupt_handler handler,
    void *handler_context,
    int level_triggered
)
{
    if (rp1 == (os_pi5_rp1_pci *)0 || !rp1->ready
        || mip == (os_pi5_bcm2712_mip *)0 || !mip->ready
        || vector >= OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT
        || handler == (os_pi5_interrupt_handler)0
        || rp1->vectors[vector].active) {
        return 0;
    }

    os_pi5_rp1_msix_vector *state = &rp1->vectors[vector];
    if (!rp1_msix_update_function_control(
            rp1, OS_PI5_PCI_MSIX_CONTROL_ENABLE
                | OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK, 0u)
        || !rp1_msix_read_entry(rp1, vector, state->original_entry)) {
        (void)rp1_msix_restore_function_state(rp1);
        return 0;
    }
    state->entry_saved = 1u;
    if (!rp1_msix_mask_entry(rp1, vector, 1)) {
        if (rp1_msix_write_entry(
                rp1, vector, state->original_entry)) {
            state->entry_saved = 0u;
            (void)rp1_msix_restore_function_state(rp1);
        }
        return 0;
    }
    state->handler = handler;
    state->handler_context = handler_context;
    state->level_triggered = (u8)(level_triggered != 0);
    os_pi5_msi_message message = {
        .address = 0u,
        .data = 0u,
    };
    if (!os_pi5_bcm2712_mip_allocate(
            mip, rp1_msix_interrupt, state, &state->vector, &message)) {
        if (state->vector.active) {
            rp1->mip = mip;
            state->active = 1u;
            ++rp1->active_vector_count;
            (void)os_pi5_rp1_pci_msix_unbind(rp1, vector);
        } else {
            if (rp1_msix_write_entry(
                    rp1, vector, state->original_entry)) {
                state->entry_saved = 0u;
                state->handler = (os_pi5_interrupt_handler)0;
                state->handler_context = (void *)0;
                state->level_triggered = 0u;
                (void)rp1_msix_restore_function_state(rp1);
            }
        }
        return 0;
    }
    rp1->mip = mip;
    state->rp1 = rp1;
    state->active = 1u;
    ++rp1->active_vector_count;
    u32 entry[OS_PI5_PCI_MSIX_TABLE_ENTRY_SIZE / sizeof(u32)];
    entry[0] = (u32)message.address;
    entry[1] = (u32)(message.address >> 32);
    entry[2] = message.data;
    entry[3] = state->original_entry[3]
        | OS_PI5_PCI_MSIX_TABLE_VECTOR_MASK;
    if (!rp1_msix_write_entry(rp1, vector, entry)) {
        (void)os_pi5_rp1_pci_msix_unbind(rp1, vector);
        return 0;
    }
    if (state->level_triggered
        && !os_pi5_rp1_pci_msix_cfg_set(
            rp1, vector, OS_PI5_RP1_PCI_MSIX_CFG_IACK_EN)) {
        (void)os_pi5_rp1_pci_msix_unbind(rp1, vector);
        return 0;
    } else if (state->level_triggered) {
        state->source_enabled = 1u;
    }
    if (!os_pi5_rp1_pci_msix_cfg_set(
            rp1, vector, OS_PI5_RP1_PCI_MSIX_CFG_ENABLE
                | OS_PI5_RP1_PCI_MSIX_CFG_IACK)) {
        (void)os_pi5_rp1_pci_msix_unbind(rp1, vector);
        return 0;
    }
    state->source_enabled = 1u;
    if (!rp1_msix_update_function_control(
            rp1, OS_PI5_PCI_MSIX_CONTROL_ENABLE,
            OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK)
        || !rp1_msix_mask_entry(rp1, vector, 0)) {
        (void)os_pi5_rp1_pci_msix_unbind(rp1, vector);
        return 0;
    }
    return 1;
}

int os_pi5_rp1_pci_msix_bind_device(
    os_pi5_rp1_pci *rp1,
    os_pi5_bcm2712_mip *mip,
    const os_device_tree *tree,
    const os_device_tree_node *device_node,
    usize interrupt_index,
    os_pi5_interrupt_handler handler,
    void *handler_context
)
{
    if (handler == (os_pi5_interrupt_handler)0
        || !rp1_child_node_valid(rp1, tree, device_node)) {
        return 0;
    }
    int interrupt_parent_is_ancestor = 0;
    usize ancestor_index = tree->node_count;
    for (usize depth = 0; depth < tree->node_count; ++depth) {
        if (ancestor_index == tree->node_count) {
            for (usize i = 0; i < tree->node_count; ++i) {
                if (&tree->nodes[i] == device_node) {
                    ancestor_index = i;
                    break;
                }
            }
            if (ancestor_index == tree->node_count) {
                return 0;
            }
        }
        if (ancestor_index == device_node->interrupt_parent_index) {
            interrupt_parent_is_ancestor = 1;
        }
        if (tree->nodes[ancestor_index].parent_index
            == OS_DEVICE_TREE_NO_PARENT) {
            break;
        }
        u16 parent_index = tree->nodes[ancestor_index].parent_index;
        if (parent_index == OS_DEVICE_TREE_NO_PARENT
            || parent_index >= tree->node_count) {
            break;
        }
        ancestor_index = parent_index;
    }
    if (!interrupt_parent_is_ancestor) {
        return 0;
    }

    os_device_tree_interrupt interrupt;
    if (!os_device_tree_get_rp1_interrupt(
            tree, device_node, interrupt_index, &interrupt)) {
        return 0;
    }
    int level_triggered =
        interrupt.flags == 4u || interrupt.flags == 8u;
    return os_pi5_rp1_pci_msix_bind(
        rp1, mip, interrupt.interrupt_id, handler,
        handler_context, level_triggered);
}

int os_pi5_rp1_pci_msix_unbind(
    os_pi5_rp1_pci *rp1,
    u32 vector
)
{
    if (rp1 == (os_pi5_rp1_pci *)0 || !rp1->ready
        || vector >= OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT
        || !rp1->vectors[vector].active
        || rp1->mip == (os_pi5_bcm2712_mip *)0
        || rp1->active_vector_count == 0u) {
        return 0;
    }
    os_pi5_rp1_msix_vector *state = &rp1->vectors[vector];
    if (!rp1_msix_update_function_control(
            rp1, OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK, 0u)
        || !rp1_msix_mask_entry(rp1, vector, 1)) {
        return 0;
    }
    if (state->source_enabled
        && (!os_pi5_rp1_pci_msix_cfg_clear(
                rp1, vector, OS_PI5_RP1_PCI_MSIX_CFG_ENABLE
                    | OS_PI5_RP1_PCI_MSIX_CFG_IACK_EN)
            || !os_pi5_rp1_pci_msix_cfg_set(
                rp1, vector, OS_PI5_RP1_PCI_MSIX_CFG_IACK))) {
        return 0;
    }
    if (!state->entry_saved
        || !rp1_msix_write_entry(rp1, vector, state->original_entry)
        || !os_pi5_bcm2712_mip_release(rp1->mip, &state->vector)) {
        return 0;
    }
    state->handler = (os_pi5_interrupt_handler)0;
    state->handler_context = (void *)0;
    state->rp1 = rp1;
    state->active = 0u;
    state->level_triggered = 0u;
    state->entry_saved = 0u;
    state->source_enabled = 0u;
    --rp1->active_vector_count;
    if (rp1->active_vector_count == 0u) {
        if (!rp1_msix_update_function_control(
                rp1, OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK,
                OS_PI5_PCI_MSIX_CONTROL_ENABLE)) {
            return 0;
        }
    } else if (!rp1_msix_update_function_control(
            rp1, OS_PI5_PCI_MSIX_CONTROL_ENABLE,
            OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK)) {
        return 0;
    }
    return 1;
}

int os_pi5_rp1_pci_cleanup(
    os_pi5_rp1_pci *rp1,
    os_pi5_bcm2712_pcie_host *host,
    os_pi5_pcie_resource_allocator *allocator
)
{
    if (rp1 == (os_pi5_rp1_pci *)0
        || (!rp1->ready && !rp1->initialization_failed)
        || host == (os_pi5_bcm2712_pcie_host *)0
        || allocator == (os_pi5_pcie_resource_allocator *)0) {
        return 0;
    }
    rp1->host = host;
    for (u32 i = 0; i < OS_PI5_RP1_PCI_MSIX_VECTOR_COUNT; ++i) {
        if (rp1->vectors[i].active
            && !os_pi5_rp1_pci_msix_unbind(rp1, i)) {
            return 0;
        }
        if (rp1->ready && !rp1->vectors[i].active
            && rp1->vectors[i].entry_saved) {
            if (!rp1_msix_update_function_control(
                    rp1, OS_PI5_PCI_MSIX_CONTROL_FUNCTION_MASK, 0u)
                || !rp1_msix_write_entry(
                    rp1, i, rp1->vectors[i].original_entry)) {
                return 0;
            }
            rp1->vectors[i].entry_saved = 0u;
            rp1->vectors[i].handler = (os_pi5_interrupt_handler)0;
            rp1->vectors[i].handler_context = (void *)0;
            rp1->vectors[i].level_triggered = 0u;
        }
    }
    if (rp1->msix_control_saved) {
        u32 control_word = 0u;
        if (!os_pi5_bcm2712_pcie_config_read32(
                host, rp1->function.bus, rp1->function.device,
                rp1->function.function, rp1->msix.capability_offset,
                &control_word)
            || !os_pi5_bcm2712_pcie_config_write32(
                host, rp1->function.bus, rp1->function.device,
                rp1->function.function, rp1->msix.capability_offset,
                (control_word & 0x0000ffffu)
                    | ((u32)rp1->original_msix_control << 16))
            || !os_pi5_bcm2712_pcie_config_read32(
                host, rp1->function.bus, rp1->function.device,
                rp1->function.function, rp1->msix.capability_offset,
                &control_word)
            || (u16)(control_word >> 16)
                != rp1->original_msix_control) {
            return 0;
        }
        rp1->msix_control_saved = 0u;
    }
    for (u32 i = OS_PI5_PCI_MAX_BARS; i != 0u; --i) {
        os_pi5_pcie_bar_resource *resource = &rp1->bars[i - 1u];
        if (resource->active
            && !os_pi5_pcie_bar_resource_cleanup(
                host, allocator, resource)) {
            return 0;
        }
    }
    os_pi5_rp1_pci_init_state(rp1);
    return 1;
}
